    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (13, N'A86356366', N'Bộ Kĩ Thuật Điện Lớp 5 Mic (2 Động Cơ)', N'Bộ Kĩ Thuật Điện Lớp 5 Mic (2 Động Cơ)', N'Mic', N'do-ban', N'multicolor', 252000.00, 0, N'Bộ Kĩ Thuật Điện Lớp 5 Mic Gồm các vật liệu cần thiết để tạo nên một mạch điện đơn giản Bộ sản phẩm gồm nhiều mảnh vật liệu tạo thành một mạch điện đơn giản giúp cho bóng đèn phát sáng. Cấu tạo sản phẩm dễ dàng lắp ráp, giúp học sinh thực hành các bài học một cách nhanh chóng, hiệu quả. Sử dụng nguồn pin AA nên cực kỳ an toàn cho học sinh khi thực hành các bài tập về điện Bộ sản phẩm gồm: Pin 1.5V, bóng đèn 1.5V - 2.5V, 2 đoạn dây, một số mảnh vật liệu dẫn điện, cách điện Thiết kế hộp đựng tiện ', N'Bộ Kĩ Thuật Điện Lớp 5 Mic Gồm các vật liệu cần thiết để tạo nên một mạch điện đơn giản Bộ sản phẩm gồm nhiều mảnh vật liệu tạo thành một mạch điện đơn giản giúp cho bóng đèn phát sáng. Cấu tạo sản phẩm dễ dàng lắp ráp, giúp học sinh thực hành các bài học một cách nhanh chóng, hiệu quả. Sử dụng nguồn pin AA nên cực kỳ an toàn cho học sinh khi thực hành các bài tập về điện Bộ sản phẩm gồm: Pin 1.5V, bóng đèn 1.5V - 2.5V, 2 đoạn dây, một số mảnh vật liệu dẫn điện, cách điện Thiết kế hộp đựng tiện ', N'images/catalog/adcbook/ADC86356366_01.webp', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (14, N'A86355896', N'Túi Dây Kéo A5 - Deli EF281 Màu Ngẫu Nhiên', N'Túi Dây Kéo A5 - Deli EF281 Màu Ngẫu Nhiên', N'Deli', N'luu-tru', N'multicolor', 15000.00, 0, N'Túi Dây Kéo A5 - Deli EF281 Sản phẩm với chất liệu nhựa trong bền, đẹp. Sản phẩm có dây khóa kéo chắc chắn, trơn tru. Dùng đựng giấy tờ, tài liệu hoặc những vật dụng cá nhân để gọn gàng, tránh bị thất lạc.', N'Túi Dây Kéo A5 - Deli EF281 Sản phẩm với chất liệu nhựa trong bền, đẹp. Sản phẩm có dây khóa kéo chắc chắn, trơn tru. Dùng đựng giấy tờ, tài liệu hoặc những vật dụng cá nhân để gọn gàng, tránh bị thất lạc.', N'images/catalog/adcbook/ADC86355896_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (15, N'A86355416', N'Khay Cắm bút gỗ HX-7022', N'Khay Cắm bút gỗ HX-7022', N'Cường Liên', N'but-viet', N'brown', 70000.00, 0, N'Khay Cắm Bút Gỗ HX-7022 - Sản phẩm được thiết kế với kiểu dáng hiện đại, giúp bạn bảo quản bút, thước, vật dụng trên bàn làm việc một cách gọn gàng, ngăn nắp. - Sản phẩm được làm bằng chất liệu gỗ cao cấp, thân thiện với môi trường và đảm bảo an toàn cho sức khoẻ. - Màu nâu với vân gỗ sang trọng, thể hiện tính thẩm mỹ cao. - Gỗ ép tự nhiên qua xử lý bằng công nghệ hiện đại, chắc chắc, chống mục, chống giòn gãy.', N'Khay Cắm Bút Gỗ HX-7022 - Sản phẩm được thiết kế với kiểu dáng hiện đại, giúp bạn bảo quản bút, thước, vật dụng trên bàn làm việc một cách gọn gàng, ngăn nắp. - Sản phẩm được làm bằng chất liệu gỗ cao cấp, thân thiện với môi trường và đảm bảo an toàn cho sức khoẻ. - Màu nâu với vân gỗ sang trọng, thể hiện tính thẩm mỹ cao. - Gỗ ép tự nhiên qua xử lý bằng công nghệ hiện đại, chắc chắc, chống mục, chống giòn gãy.', N'images/catalog/adcbook/ADC86355416_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (16, N'A86353924', N'Bấm Kim Mini Basic Số 10 - Thiên Long ST-020 (Nhiều Màu)', N'Bấm Kim Mini Basic Số 10 - Thiên Long ST-020 (Nhiều Màu)', N'Thiên Long', N'dung-cu', N'multicolor', 18000.00, 0, N'Bấm Kim Mini Basic Số 10 - Thiên Long ST-020 Bấm Kim Mini Số 10 được thiết kế mới với lực bấm nhẹ, cho khả năng bấm nhanh và chuẩn xác, không làm bung kim hay rách giấy. Bấm nhẹ, không ghẹt kim, màu sắc trẻ trung, kiểu dáng đẹp mắt Thiết kế nhỏ gọn dễ cầm và bấm, có kèm dụng cụ gỡ kim rất tiện lợi Kim bấm có thể bấm được nhiều tờ một cách chính xác và nhanh chóng, giúp bạn tiết kiệm được nhiều thời gian. Đồng thời, tài liệu của bạn cũng được sắp xếp gọn gàng và khoa học hơn, tránh tình trạng bị ', N'Bấm Kim Mini Basic Số 10 - Thiên Long ST-020 Bấm Kim Mini Số 10 được thiết kế mới với lực bấm nhẹ, cho khả năng bấm nhanh và chuẩn xác, không làm bung kim hay rách giấy. Bấm nhẹ, không ghẹt kim, màu sắc trẻ trung, kiểu dáng đẹp mắt Thiết kế nhỏ gọn dễ cầm và bấm, có kèm dụng cụ gỡ kim rất tiện lợi Kim bấm có thể bấm được nhiều tờ một cách chính xác và nhanh chóng, giúp bạn tiết kiệm được nhiều thời gian. Đồng thời, tài liệu của bạn cũng được sắp xếp gọn gàng và khoa học hơn, tránh tình trạng bị ', N'images/catalog/adcbook/ADC86353924_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (17, N'A86353605', N'Phiếu chi A5 2, 3 liên 60 tờ (Thúy)', N'Phiếu chi A5 2, 3 liên 60 tờ (Thúy)', N'CN Công ty TNHH SX VPP TM Hán Sơn (Thúy Hưng)', N'luu-tru', N'multicolor', 18000.00, 0, N'Phiếu chi 2 liên, 3 liên được in trên chất liệu giấy cacbon khi bạn ghi lên bề mặt trang trên thì nội dung đó sẽ được in đè từ mặt sau của trang trên xuống tờ giấy để phía dưới nó – có tác dụng như giấy than', N'Phiếu chi 2 liên, 3 liên được in trên chất liệu giấy cacbon khi bạn ghi lên bề mặt trang trên thì nội dung đó sẽ được in đè từ mặt sau của trang trên xuống tờ giấy để phía dưới nó – có tác dụng như giấy than', N'images/catalog/adcbook/ADC86353605_01.png', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (18, N'A86352797', N'Giá Tài Liệu 3 Tầng E9213 Màu Xanh (Deli)', N'Giá Tài Liệu 3 Tầng E9213 Màu Xanh (Deli)', N'CÔNG TY TNHH PHÁT TRIỂN DELI VIỆT NAM (mã mới)', N'luu-tru', N'blue', 189000.00, 0, N'Khay Nhựa 3 Tầng Deli E9213 là lựa chọn lý tưởng để sắp xếp giấy tờ và hồ sơ một cách khoa học. Được chế tạo từ nhựa cao cấp, khay có độ bền cao, không bị nứt gãy, dễ vệ sinh và an toàn khi sử dụng. Thiết kế 3 tầng chồng chắc chắn, tối ưu diện tích bàn làm việc, đồng thời giữ tài liệu luôn ngăn nắp và dễ tìm kiếm. Sản phẩm phù hợp cho văn phòng, trường học, cửa hàng hoặc gia đình có nhiều giấy tờ cần lưu trữ.', N'Khay Nhựa 3 Tầng Deli E9213 là lựa chọn lý tưởng để sắp xếp giấy tờ và hồ sơ một cách khoa học. Được chế tạo từ nhựa cao cấp, khay có độ bền cao, không bị nứt gãy, dễ vệ sinh và an toàn khi sử dụng. Thiết kế 3 tầng chồng chắc chắn, tối ưu diện tích bàn làm việc, đồng thời giữ tài liệu luôn ngăn nắp và dễ tìm kiếm. Sản phẩm phù hợp cho văn phòng, trường học, cửa hàng hoặc gia đình có nhiều giấy tờ cần lưu trữ.', N'images/catalog/adcbook/ADC86352797_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (19, N'A86343308', N'Túi 1 Cúc Khổ A TCT012', N'Túi 1 Cúc Khổ A TCT012', N'TCT', N'luu-tru', N'white', 4000.00, 0, N'Túi clear bag khổ A TCT012 - Loại dày hay túi hồ sơ dùng để lưu trữ đựng hồ sơ giấy tờ hoặc các hợp đồng ... THÔNG TIN CHI TIẾT SẢN PHẨM: - Túi làm bằng chất liệu nhựa nguyên chất trong dẻo dai - Màu sắc trong suốt dễ nhìn được tài liệu bên trong - Kích thước 230x330 mm (+- 2mm). - Trọng lượng : 22 g/túi (+- 0.5g) -Độ dày : 135 mic (+- 5 mic) -Công nghệ hàn: Siêu Âm chắc chắn', N'Túi clear bag khổ A TCT012 - Loại dày hay túi hồ sơ dùng để lưu trữ đựng hồ sơ giấy tờ hoặc các hợp đồng ... THÔNG TIN CHI TIẾT SẢN PHẨM: - Túi làm bằng chất liệu nhựa nguyên chất trong dẻo dai - Màu sắc trong suốt dễ nhìn được tài liệu bên trong - Kích thước 230x330 mm (+- 2mm). - Trọng lượng : 22 g/túi (+- 0.5g) -Độ dày : 135 mic (+- 5 mic) -Công nghệ hàn: Siêu Âm chắc chắn', N'images/catalog/adcbook/ADC86343308_01.png', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (20, N'A85982943', N'Bìa Acco A4 Plus 82.V02 - Màu Ghi', N'Bìa Acco A4 Plus 82.V02 - Màu Ghi', N'Plus', N'luu-tru', N'grey', 16000.00, 0, N'Bìa Trình Kí Plus 82-V02 Sản phẩm với thiết kế chắc chắn, bền dai, không độc hại giúp giữ hồ sơ, giấy tờ gọn gàng để tiện cho việc ký kết hợp đồng hay ký các quyết định quan trọng Bìa cứng chắc, đường hàn có độ bền cao Kẹp bền chắc có tính đàn hồi cao giúp kẹp chặt tài liệu, hồ sơ Hai góc kép được bọc nhựa, giúp tài liệu hồ sơ không bị rơi ra khỏi kẹp Nhựa bọc ngoài mềm mại tạo cảm giác êm tay khi ký duyệt hoặc ghi chú trên hồ sơ, tài liệu', N'Bìa Trình Kí Plus 82-V02 Sản phẩm với thiết kế chắc chắn, bền dai, không độc hại giúp giữ hồ sơ, giấy tờ gọn gàng để tiện cho việc ký kết hợp đồng hay ký các quyết định quan trọng Bìa cứng chắc, đường hàn có độ bền cao Kẹp bền chắc có tính đàn hồi cao giúp kẹp chặt tài liệu, hồ sơ Hai góc kép được bọc nhựa, giúp tài liệu hồ sơ không bị rơi ra khỏi kẹp Nhựa bọc ngoài mềm mại tạo cảm giác êm tay khi ký duyệt hoặc ghi chú trên hồ sơ, tài liệu', N'images/catalog/adcbook/ADC85982943_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (21, N'A85982817', N'Túi 1 Cúc F4 Plus 89.V35 CB2636', N'Túi 1 Cúc F4 Plus 89.V35 CB2636', N'Plus', N'luu-tru', N'white', 7000.00, 0, N'Bìa Nút Trong F4 Plus (0.15mm) 89-V35 Sản phẩm được thiết kế như một bao thư cỡ lớn, có nắp kín và nút bấm chắc chắn giúp giữ cho tài liệu luôn nằm gọn bên trong, tránh thất lạc. Bìa được làm từ nhựa cao cấp, chống thấm nước, chống bám bụi, bảo quản an toàn cho giấy tờ của bạn. Sản phẩm có thể lưu trữ được các hồ sơ, giấy tờ ở kích cỡ A4. Bìa có màu sắc trong suốt giúp bạn dễ quan sát giấy tờ bên trong, tiện lợi khi tìm kiếm. Sản phẩm không thể thiếu của giới học sinh, sinh viên và nhân viên văn', N'Bìa Nút Trong F4 Plus (0.15mm) 89-V35 Sản phẩm được thiết kế như một bao thư cỡ lớn, có nắp kín và nút bấm chắc chắn giúp giữ cho tài liệu luôn nằm gọn bên trong, tránh thất lạc. Bìa được làm từ nhựa cao cấp, chống thấm nước, chống bám bụi, bảo quản an toàn cho giấy tờ của bạn. Sản phẩm có thể lưu trữ được các hồ sơ, giấy tờ ở kích cỡ A4. Bìa có màu sắc trong suốt giúp bạn dễ quan sát giấy tờ bên trong, tiện lợi khi tìm kiếm. Sản phẩm không thể thiếu của giới học sinh, sinh viên và nhân viên văn', N'images/catalog/adcbook/ADC85982817_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (22, N'A85973959', N'Bìa Còng A4 5cm Lanrch 800-V017 Xanh Dương', N'Bìa Còng A4 5cm Lanrch 800-V017 Xanh Dương', N'Plus', N'luu-tru', N'blue', 67000.00, 0, N'Bìa Còng A4 Plus 5cm 800-V017 - Màu Xanh Dương Sản phẩm được làm từ carton cứng, có độ bền cao, chịu va đập tốt. Sản phẩm không thấm nước, dễ dàng làm sạch lau chùi, giúp sắp xếp tài liệu dễ dàng. Khóa còng là kim loại phủ niken sáng bóng, chống gỉ sét, chống bám bụi, có thể đóng mở nhiều lần để thêm bớt tài liệu mà không bị cong vênh. Sản phẩm có kích cỡ bằng khổ giấy A4, phù hợp với đa số các loại giấy tờ hiện nay, là sản phẩm lý tưởng để lưu trữ hồ sơ, giấy tờ quan trọng không bị nhăn, nhàu. ', N'Bìa Còng A4 Plus 5cm 800-V017 - Màu Xanh Dương Sản phẩm được làm từ carton cứng, có độ bền cao, chịu va đập tốt. Sản phẩm không thấm nước, dễ dàng làm sạch lau chùi, giúp sắp xếp tài liệu dễ dàng. Khóa còng là kim loại phủ niken sáng bóng, chống gỉ sét, chống bám bụi, có thể đóng mở nhiều lần để thêm bớt tài liệu mà không bị cong vênh. Sản phẩm có kích cỡ bằng khổ giấy A4, phù hợp với đa số các loại giấy tờ hiện nay, là sản phẩm lý tưởng để lưu trữ hồ sơ, giấy tờ quan trọng không bị nhăn, nhàu. ', N'images/catalog/adcbook/ADC85973959_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (23, N'A85973834', N'Bìa Sơ Mi Lỗ LN026 Loại Dày 100T/Tập', N'Bìa Sơ Mi Lỗ LN026 Loại Dày 100T/Tập', N'Long Nguyên', N'luu-tru', N'white', 80000.00, 0, N'THÔNG TIN SẢN PHẨM: - Tên sản phẩm: Bìa Sơ Mi Lỗ LN026 - Mã sản phẩm: LN026 - Thương hiệu: Long Nguyên - Xuất xứ: Việt Nam - Màu sắc: trong suốt ĐẶC TÍNH NỔI BẬT: - Chất liệu chịu được sự hao mòn trong khoảng thời gian dài - Chất liệu trong suốt dễ nhìn, dễ theo dõi tài liệu - Kích thước khổ A4, phù hợp để đựng các hóa đơn, chứng từ, giấy tờ…Khổ A4, A5. - File hồ sơ chất liệu từ nhựa PP, nhựa qua quy trình xử lý loại bỏ các tạp chất nguy hại. An toàn với sức khỏe người sử', N'THÔNG TIN SẢN PHẨM: - Tên sản phẩm: Bìa Sơ Mi Lỗ LN026 - Mã sản phẩm: LN026 - Thương hiệu: Long Nguyên - Xuất xứ: Việt Nam - Màu sắc: trong suốt ĐẶC TÍNH NỔI BẬT: - Chất liệu chịu được sự hao mòn trong khoảng thời gian dài - Chất liệu trong suốt dễ nhìn, dễ theo dõi tài liệu - Kích thước khổ A4, phù hợp để đựng các hóa đơn, chứng từ, giấy tờ…Khổ A4, A5. - File hồ sơ chất liệu từ nhựa PP, nhựa qua quy trình xử lý loại bỏ các tạp chất nguy hại. An toàn với sức khỏe người sử', N'images/catalog/adcbook/ADC85973834_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
