    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (25, N'A85611531', N'Bìa Còng A4 7cm Lanrch 800-V031 Xanh Dương (Bản Mới)', N'Bìa Còng A4 7cm Lanrch 800-V031 Xanh Dương (Bản Mới)', N'Plus', N'luu-tru', N'blue', 69000.00, 0, N'Bìa Còng 1 Mặt Si A4 7cm - Plus 800-V031 - Màu Xanh Dương - Được làm từ chất liệu Simili cao cấp, bìa còng có khả năng chống bám bẩn, dễ lau chùi. Còng kim loại sáng bóng, chắc chắn, chống gỉ sét, đảm bảo độ bền cao khi sử dụng lâu dài. - Phù hợp để cố định và lưu trữ số lượng lớn tài liệu, hồ sơ một cách ngăn nắp và khoa học. Sản phẩm giúp bảo vệ giấy tờ khỏi bụi bẩn, đồng thời dễ dàng sắp xếp các loại giấy tờ, tài liệu có đóng lỗ hoặc sử dụng bìa lỗ đi kèm.', N'Bìa Còng 1 Mặt Si A4 7cm - Plus 800-V031 - Màu Xanh Dương - Được làm từ chất liệu Simili cao cấp, bìa còng có khả năng chống bám bẩn, dễ lau chùi. Còng kim loại sáng bóng, chắc chắn, chống gỉ sét, đảm bảo độ bền cao khi sử dụng lâu dài. - Phù hợp để cố định và lưu trữ số lượng lớn tài liệu, hồ sơ một cách ngăn nắp và khoa học. Sản phẩm giúp bảo vệ giấy tờ khỏi bụi bẩn, đồng thời dễ dàng sắp xếp các loại giấy tờ, tài liệu có đóng lỗ hoặc sử dụng bìa lỗ đi kèm.', N'images/catalog/adcbook/ADC85611531_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (26, N'A85594458', N'Giấy Foto A4 IK PLUS DL70 Vỏ Xanh Cốm', N'Giấy Foto A4 IK PLUS DL70 Vỏ Xanh Cốm', N'CÔNG TY TNHH VĂN PHÒNG PHẨM LAN ANH (Thanh toán cuối tháng)', N'so-giay', N'white', 93000.00, 1, N'Giấy IK Plus có độ sáng cao và độ dày được cải thiện, mang lại độ tương phản, độ rõ nét và chất lượng in ấn tuyệt vời cho tài liệu. Loại giấy cao cấp này đảm bảo hiệu suất hoạt động không gặp sự cố trên thiết bị văn phòng của bạn. - Đặc điểm: Độ trắng cao và độ sáng cao; Độ mờ cao cho phép in hai mặt - Độ dày cao và độ mịn tối ưu giúp máy photocopy hoạt động trơn tru - Chứng nhận PEFC. 1 thùng = 5 Ream; 1 Ream = 500 tờ.', N'Giấy IK Plus có độ sáng cao và độ dày được cải thiện, mang lại độ tương phản, độ rõ nét và chất lượng in ấn tuyệt vời cho tài liệu. Loại giấy cao cấp này đảm bảo hiệu suất hoạt động không gặp sự cố trên thiết bị văn phòng của bạn. - Đặc điểm: Độ trắng cao và độ sáng cao; Độ mờ cao cho phép in hai mặt - Độ dày cao và độ mịn tối ưu giúp máy photocopy hoạt động trơn tru - Chứng nhận PEFC. 1 thùng = 5 Ream; 1 Ream = 500 tờ.', N'images/catalog/adcbook/ADC85594458_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (27, N'A83983235', N'Dập Ghim Deli Mini 0452 No.10 Kèm Ghim (Deli)', N'Dập Ghim Deli Mini 0452 No.10 Kèm Ghim (Deli)', N'Deli', N'dung-cu', N'multicolor', 48000.00, 0, N'Dập Ghim Deli 0452 là mẫu dập ghim mini nhỏ gọn, tiện lợi, phù hợp cho học sinh, sinh viên, nhân viên văn phòng và gia đình. Với thiết kế hiện đại cùng chất liệu nhựa cao cấp kết hợp khung thép chắc chắn, sản phẩm mang lại thao tác bấm nhẹ nhàng, đóng ghim chính xác và bền bỉ trong quá trình sử dụng. Sản phẩm sử dụng kim bấm số 10 thông dụng, có khả năng bấm tối đa 15 tờ giấy, đáp ứng tốt nhu cầu lưu trữ tài liệu hằng ngày.', N'Dập Ghim Deli 0452 là mẫu dập ghim mini nhỏ gọn, tiện lợi, phù hợp cho học sinh, sinh viên, nhân viên văn phòng và gia đình. Với thiết kế hiện đại cùng chất liệu nhựa cao cấp kết hợp khung thép chắc chắn, sản phẩm mang lại thao tác bấm nhẹ nhàng, đóng ghim chính xác và bền bỉ trong quá trình sử dụng. Sản phẩm sử dụng kim bấm số 10 thông dụng, có khả năng bấm tối đa 15 tờ giấy, đáp ứng tốt nhu cầu lưu trữ tài liệu hằng ngày.', N'images/catalog/adcbook/ADC83983235_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (28, N'A82795657', N'Dao Rọc Giấy 2031 DELI 1 Lưỡi Khóa Tự Động', N'Dao Rọc Giấy 2031 DELI 1 Lưỡi Khóa Tự Động', N'Deli', N'so-giay', N'yellow', 29000.00, 0, N'Dao rọc giấy trung Deli E2031 Phần thân được bọc nhựa, tay cầm cũng có các đường vân chống trượt giúp bạn dễ dàng cố định dao, lưỡi dao làm bằng hợp kim thép cao cấp, sắc bén không rỉ. Công dụng: Dùng để cắt, rọc giấy, gọt bút chì, rọc vải, cắt tỉa hoa quả…', N'Dao rọc giấy trung Deli E2031 Phần thân được bọc nhựa, tay cầm cũng có các đường vân chống trượt giúp bạn dễ dàng cố định dao, lưỡi dao làm bằng hợp kim thép cao cấp, sắc bén không rỉ. Công dụng: Dùng để cắt, rọc giấy, gọt bút chì, rọc vải, cắt tỉa hoa quả…', N'images/catalog/adcbook/ADC82795657_01.webp', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (29, N'A64543899', N'Kéo Văn Phòng EM600 Nhiều Màu (Deli)', N'Kéo Văn Phòng EM600 Nhiều Màu (Deli)', N'Deli', N'dung-cu', N'multicolor', 28000.00, 0, N'Kéo Văn Phòng Deli EM600 thiết kế mũi kéo nhọn, dài và sắc bén cho phép bạn cắt các loại giấy, vải hoặc bìa thật dễ dàng trong thời gian ngắn. Kéo có màu nâu và đen tinh tế, đẹp mắt cho bạn lựa chọn. Kéo được bọc thêm lớp nhựa ở cán, tạo cảm giác êm ái và thoải mái cho bạn khi cắt. Lưỡi kéo làm từ hợp kim thép cao cấp Kéo Deli chế tác phần lưỡi cắt từ chất liệu hợp kim thép cao cấp có độ sắc bén hoàn hảo giúp bạn cắt giấy, vải,.. thật dễ dàng', N'Kéo Văn Phòng Deli EM600 thiết kế mũi kéo nhọn, dài và sắc bén cho phép bạn cắt các loại giấy, vải hoặc bìa thật dễ dàng trong thời gian ngắn. Kéo có màu nâu và đen tinh tế, đẹp mắt cho bạn lựa chọn. Kéo được bọc thêm lớp nhựa ở cán, tạo cảm giác êm ái và thoải mái cho bạn khi cắt. Lưỡi kéo làm từ hợp kim thép cao cấp Kéo Deli chế tác phần lưỡi cắt từ chất liệu hợp kim thép cao cấp có độ sắc bén hoàn hảo giúp bạn cắt giấy, vải,.. thật dễ dàng', N'images/catalog/adcbook/ADC64543899_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
