    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (32, N'A54900210', N'Kéo Văn Phòng Em609 Màu Lẫn (Deli)', N'Kéo Văn Phòng Em609 Màu Lẫn (Deli)', N'Deli', N'luu-tru', N'multicolor', 31000.00, 0, N'Kéo Văn Phòng 160 mm - Deli EM609 Tính Năng Sản Phẩm - Lưỡi kéo sắc bén : giúp cắt giấy, bìa cứng dễ dàng. - Chất liệu thép không gỉ : có độ bền cao, chống mài mòn. - Tay cầm bằng nhựa cao cấp : thiết kế vừa vặn, êm ái khi sử dụng. - Thiết kế đinh tán chắc chắn : giúp kéo hoạt động ổn định và bền bỉ.', N'Kéo Văn Phòng 160 mm - Deli EM609 Tính Năng Sản Phẩm - Lưỡi kéo sắc bén : giúp cắt giấy, bìa cứng dễ dàng. - Chất liệu thép không gỉ : có độ bền cao, chống mài mòn. - Tay cầm bằng nhựa cao cấp : thiết kế vừa vặn, êm ái khi sử dụng. - Thiết kế đinh tán chắc chắn : giúp kéo hoạt động ổn định và bền bỉ.', N'images/catalog/adcbook/ADC54900210_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (33, N'A54900194', N'Dao Rọc Giấy Deli 2054 (Deli)', N'Dao Rọc Giấy Deli 2054 (Deli)', N'Deli', N'so-giay', N'multicolor', 12000.00, 0, N'Dao Rọc Giấy - Deli 2054 Sản phẩm à dụng cụ tiện lợi, thích hợp sử dụng trong trường học, bệnh viện. Lưỡi dao làm bằng kim loại sắc bén, cho đường cắt dứt khoát và đẹp mắt, không bị gỉ sét sau một thời gian sử dụng. Thân dao cắt làm bằng chất liệu kim loại chắc chắn, sơn nhiều màu sắc trẻ trung hiện đại. Cấu tạo sản phẩm an toàn, phần tay cầm bọc nhựa chắc chắn, tránh bị cắt phạm vào tay.', N'Dao Rọc Giấy - Deli 2054 Sản phẩm à dụng cụ tiện lợi, thích hợp sử dụng trong trường học, bệnh viện. Lưỡi dao làm bằng kim loại sắc bén, cho đường cắt dứt khoát và đẹp mắt, không bị gỉ sét sau một thời gian sử dụng. Thân dao cắt làm bằng chất liệu kim loại chắc chắn, sơn nhiều màu sắc trẻ trung hiện đại. Cấu tạo sản phẩm an toàn, phần tay cầm bọc nhựa chắc chắn, tránh bị cắt phạm vào tay.', N'images/catalog/adcbook/ADC54900194_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (34, N'A54900044', N'Vở Kẻ Ngang Hồng Hà Study Stripe A4 1458 120Tr', N'Vở Kẻ Ngang Hồng Hà Study Stripe A4 1458 120Tr', N'Hồng Hà', N'so-giay', N'multicolor', 24000.00, 0, N'Vở kẻ ngang A4 Hồng Hà Study Tem 120 trang - 1458 thiết kế tập trung vào sự tối giản, sáng tạo và tối ưu hóa theo chủ đề "Tem" mang tới sự thoải mái, tập trung cho người dùng. Kích thước A4 giúp người dùng có thêm nhiều không gian ghi chép và sáng tạo nội dung. 2. THÔNG SỐ KĨ THUẬT Dòng kẻ: Kẻ ngang (7mm) Kích thước: 210 x 297 (±2mm) Số trang: 120 trang cả bìa Định lượng: 70gsm Độ trắng: 90 - 92% ISO Đóng gói: 5 quyển/lốc, 80 quyển/thùng Xuất xứ vở: Việt Nam. 3. ĐẶC ĐIỂM SẢN PHẨM Bề mặt giấy lán', N'Vở kẻ ngang A4 Hồng Hà Study Tem 120 trang - 1458 thiết kế tập trung vào sự tối giản, sáng tạo và tối ưu hóa theo chủ đề "Tem" mang tới sự thoải mái, tập trung cho người dùng. Kích thước A4 giúp người dùng có thêm nhiều không gian ghi chép và sáng tạo nội dung. 2. THÔNG SỐ KĨ THUẬT Dòng kẻ: Kẻ ngang (7mm) Kích thước: 210 x 297 (±2mm) Số trang: 120 trang cả bìa Định lượng: 70gsm Độ trắng: 90 - 92% ISO Đóng gói: 5 quyển/lốc, 80 quyển/thùng Xuất xứ vở: Việt Nam. 3. ĐẶC ĐIỂM SẢN PHẨM Bề mặt giấy lán', N'images/catalog/adcbook/ADC54900044_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (35, N'A54899211', N'Giấy Note Deli 3''''*3'''' EA603-Vn Màu Vàng', N'Giấy Note Deli 3''''*3'''' EA603-Vn Màu Vàng', N'Deli', N'so-giay', N'multicolor', 13000.00, 0, N'Giấy Note 76 x 76 mm 75gsm - Deli EA603 - Màu Vàng (100 Tờ) Sản phẩm tiện lợi trong việc ghi chú lại thông tin quan trọng. Keo dán chắc chắn, khó có tình trạng rơi rớt giấy sau khi note và dán thông tin lên các chất liệu khác. Độ bám dính lâu bền với thời gian dài trong môi trường nhiệt độ ổn định. Gồm 100 tờ trong 1 xấp, có thể tháo dán và gỡ ra dễ dàng nhờ lớp keo mỏng. Sản phẩm có thể tháo dán và gỡ ra dễ dàng nhờ lớp keo mỏng.', N'Giấy Note 76 x 76 mm 75gsm - Deli EA603 - Màu Vàng (100 Tờ) Sản phẩm tiện lợi trong việc ghi chú lại thông tin quan trọng. Keo dán chắc chắn, khó có tình trạng rơi rớt giấy sau khi note và dán thông tin lên các chất liệu khác. Độ bám dính lâu bền với thời gian dài trong môi trường nhiệt độ ổn định. Gồm 100 tờ trong 1 xấp, có thể tháo dán và gỡ ra dễ dàng nhờ lớp keo mỏng. Sản phẩm có thể tháo dán và gỡ ra dễ dàng nhờ lớp keo mỏng.', N'images/catalog/adcbook/ADC54899211_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (36, N'A54898794', N'Túi Cài Đa Năng Plus Pasty A4S 89.V106 Xanh Dương', N'Túi Cài Đa Năng Plus Pasty A4S 89.V106 Xanh Dương', N'Plus', N'luu-tru', N'blue', 14000.00, 0, N'Túi Cài Đa Năng Plus Pasty A4S 89.V106 Xanh Dương Túi Cài Đa Năng S Đứng - Plus 89-V106 là sản phẩm thân thiện với môi trường, thuận tiện khi sử dụng, giúp bảo quản tài liệu của bạn tốt hơn. Với màu sắc tươi tắn và sang trọng, túi cài đa năng không chỉ là công cụ tiện dụng mà còn giúp bạn thể hiện được sự chuyên nghiệp của mình. Bìa cứng chắc, đường hàn có độ bền cao. Có khóa chặn chắc chắn giúp hồ sơ không bị xộc xệch, rơi rớt ra ngoài khi vận chuyển và lưu trữ.', N'Túi Cài Đa Năng Plus Pasty A4S 89.V106 Xanh Dương Túi Cài Đa Năng S Đứng - Plus 89-V106 là sản phẩm thân thiện với môi trường, thuận tiện khi sử dụng, giúp bảo quản tài liệu của bạn tốt hơn. Với màu sắc tươi tắn và sang trọng, túi cài đa năng không chỉ là công cụ tiện dụng mà còn giúp bạn thể hiện được sự chuyên nghiệp của mình. Bìa cứng chắc, đường hàn có độ bền cao. Có khóa chặn chắc chắn giúp hồ sơ không bị xộc xệch, rơi rớt ra ngoài khi vận chuyển và lưu trữ.', N'images/catalog/adcbook/ADC54898794_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
