    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (48, N'A52965606', N'Kẹp Bướm Màu 19mm E8555', N'Kẹp Bướm Màu 19mm E8555', N'Deli', N'luu-tru', N'multicolor', 15000.00, 0, N'Kẹp bướm màu 19mm Deli E8555 có 4 màu tươi sáng, hợp xu hướng giúp bàn làm việc nhiều màu sắc, khơi gợi cảm hứng và sáng tạo THÔNG TIN CHI TIẾT SẢN PHẨM: - Sản xuất từ chất liệu kim loại cao cấp, được phủ Niken chống gỉ giúp kẹp bướm luôn bền đẹp theo thời gian - Phần lò xo của kẹp linh hoạt, nhẹ, dễ dùng, không bị lỏng hay bung rời sau nhiều lần sử dụng - Tay cầm chắc chắn, vừa vặn tạo cảm giác thoải mái khi sử dụng - Có 4 màu tươi sáng, hợp xu hướng giúp bàn làm việc nhiều màu sắc, khơi gợi cả', N'Kẹp bướm màu 19mm Deli E8555 có 4 màu tươi sáng, hợp xu hướng giúp bàn làm việc nhiều màu sắc, khơi gợi cảm hứng và sáng tạo THÔNG TIN CHI TIẾT SẢN PHẨM: - Sản xuất từ chất liệu kim loại cao cấp, được phủ Niken chống gỉ giúp kẹp bướm luôn bền đẹp theo thời gian - Phần lò xo của kẹp linh hoạt, nhẹ, dễ dùng, không bị lỏng hay bung rời sau nhiều lần sử dụng - Tay cầm chắc chắn, vừa vặn tạo cảm giác thoải mái khi sử dụng - Có 4 màu tươi sáng, hợp xu hướng giúp bàn làm việc nhiều màu sắc, khơi gợi cả', N'images/catalog/adcbook/ADC52965606_01.webp', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (49, N'A52965605', N'Kẹp Bướm Màu E8556 (Deli)', N'Kẹp Bướm Màu E8556 (Deli)', N'Deli', N'luu-tru', N'multicolor', 63000.00, 0, N'Chất liệu hợp kim đọ bền lâu dài Kẹp bướm kim loại Bề mặt sử dụng công nghệ mạ sơn, khó bị han gỉ Có thể sử dụng trong nhiều môi trường Màu sắc: Hồng, xanh dương, xanh lá, vàng Quy cách: 60 cái/lọ Giá sản phẩm trên Tiki đã bao gồm thuế theo luật hiện hành. Bên cạnh đó, tuỳ vào loại sản phẩm, hình thức và địa chỉ giao hàng mà có thể phát sinh thêm chi phí khác như phí vận chuyển, phụ phí hàng cồng kềnh, thuế nhập khẩu (đối với đơn hàng giao từ nước ngoài có giá trị trên 1 triệu đồng).....', N'Chất liệu hợp kim đọ bền lâu dài Kẹp bướm kim loại Bề mặt sử dụng công nghệ mạ sơn, khó bị han gỉ Có thể sử dụng trong nhiều môi trường Màu sắc: Hồng, xanh dương, xanh lá, vàng Quy cách: 60 cái/lọ Giá sản phẩm trên Tiki đã bao gồm thuế theo luật hiện hành. Bên cạnh đó, tuỳ vào loại sản phẩm, hình thức và địa chỉ giao hàng mà có thể phát sinh thêm chi phí khác như phí vận chuyển, phụ phí hàng cồng kềnh, thuế nhập khẩu (đối với đơn hàng giao từ nước ngoài có giá trị trên 1 triệu đồng).....', N'images/catalog/adcbook/ADC52965605_01.webp', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (50, N'A52869227', N'Băng Keo Silicon Đa Năng 2 Mặt E685 (12mm*3m)', N'Băng Keo Silicon Đa Năng 2 Mặt E685 (12mm*3m)', N'Eras', N'do-ban', N'multicolor', 28000.00, 0, N'Băng Keo Silicon Đa Năng 2 Mặt Eras E685 Chính Hãng – Siêu Dính, Chống Nước, Dễ Sử Dụng Băng Keo Silicon Đa Năng 2 Mặt Eras E685 là dòng băng keo silicon trong suốt cao cấp có độ bám dính mạnh, chuyên dùng để cố định vật dụng, treo đồ, dán tường hoặc trang trí nội thất mà không cần khoan đục. Sản phẩm được nhiều gia đình, văn phòng và cửa hàng lựa chọn nhờ khả năng chống nước, dễ sử dụng và tính thẩm mỹ cao. * Ưu Điểm Nổi Bật Của Băng Keo Silicon Eras E685 - Siêu Dính – Bám Chắc Trên Nhiều Bề Mặ', N'Băng Keo Silicon Đa Năng 2 Mặt Eras E685 Chính Hãng – Siêu Dính, Chống Nước, Dễ Sử Dụng Băng Keo Silicon Đa Năng 2 Mặt Eras E685 là dòng băng keo silicon trong suốt cao cấp có độ bám dính mạnh, chuyên dùng để cố định vật dụng, treo đồ, dán tường hoặc trang trí nội thất mà không cần khoan đục. Sản phẩm được nhiều gia đình, văn phòng và cửa hàng lựa chọn nhờ khả năng chống nước, dễ sử dụng và tính thẩm mỹ cao. * Ưu Điểm Nổi Bật Của Băng Keo Silicon Eras E685 - Siêu Dính – Bám Chắc Trên Nhiều Bề Mặ', N'images/catalog/adcbook/ADC52869227_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (51, N'A52869223', N'Băng Keo Silicon Đa Năng 2 Mặt E686 (24mm*3m)', N'Băng Keo Silicon Đa Năng 2 Mặt E686 (24mm*3m)', N'Eras', N'do-ban', N'multicolor', 21000.00, 0, N'ƯU ĐIỂM BĂNG KEO 2 MẶT SIÊU DÍNH DÁN TƯỜNG DÁN MỌI BỀ MẶT - Kích thước: 24mm x 3M - Đóng gói: 1 túi (1 cái) - Băng keo dán siêu chắc chắn, dán được mọi đồ vật trong nhà, tiết kiệm không gian trong ngôi nhà bạn. - Băng dính 2 mặt trong suốt tái sử dụng được nhiều lần. - Băng dính có độ đàn hồi cao, chống rung động. - Bản băng keo mới không thấm nước, chống hoá chất, chống ăn mòn. - Hút dính mọi bề mặt. - Băng dính 3m tiện lợi khi đi xa, nấu ăn, làm việc, giải trí. - Băng dính dễ dàng làm sạch với', N'ƯU ĐIỂM BĂNG KEO 2 MẶT SIÊU DÍNH DÁN TƯỜNG DÁN MỌI BỀ MẶT - Kích thước: 24mm x 3M - Đóng gói: 1 túi (1 cái) - Băng keo dán siêu chắc chắn, dán được mọi đồ vật trong nhà, tiết kiệm không gian trong ngôi nhà bạn. - Băng dính 2 mặt trong suốt tái sử dụng được nhiều lần. - Băng dính có độ đàn hồi cao, chống rung động. - Bản băng keo mới không thấm nước, chống hoá chất, chống ăn mòn. - Hút dính mọi bề mặt. - Băng dính 3m tiện lợi khi đi xa, nấu ăn, làm việc, giải trí. - Băng dính dễ dàng làm sạch với', N'images/catalog/adcbook/ADC52869223_01.webp', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (52, N'A52767909', N'Bút Máy Kim Tinh Eras Có Định Vị E023 Màu Ngẫu Nhiên', N'Bút Máy Kim Tinh Eras Có Định Vị E023 Màu Ngẫu Nhiên', N'Eras', N'but-viet', N'multicolor', 19999.98, 0, N'Bút Máy Kim Tinh Eras Có Định Vị E023 (1/36/864) Bút máy kim tinh ngòi trơn siêu bền, tay cầm định vị, chống trơn trượt, thân bút in hình ảnh sống động lôi cuốn, thân nhựa nhỏ nhẹ dành cho bé tập viết. Có thể sử dụng bơm mực hoặc mực ống E222.', N'Bút Máy Kim Tinh Eras Có Định Vị E023 (1/36/864) Bút máy kim tinh ngòi trơn siêu bền, tay cầm định vị, chống trơn trượt, thân bút in hình ảnh sống động lôi cuốn, thân nhựa nhỏ nhẹ dành cho bé tập viết. Có thể sử dụng bơm mực hoặc mực ống E222.', N'images/catalog/adcbook/ADC52767909_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T08:49:12.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (53, N'A85359253', N'Bút Gel C6600S-TI 0.5mm Màu Tím 12c/Hộp (Deli)', N'Bút Gel C6600S-TI 0.5mm Màu Tím 12c/Hộp (Deli)', N'Deli', N'but-viet', N'purple', 75000.00, 1, N'Bút Gel 0.5 mm - Deli C6600S-TI - Mực Tím - Bút thường sử dụng để viết ghi chú, soạn thảo văn bản trên giấy. - Bút gel Deli, nhiều màu sắc cho bạn lựa chọn - Nét bút mượt mà, màu sắc tươi sáng - Phù hợp với người đi làm, học sinh, sinh viên. - Bút có đầu bi sử dụng vật liệu cao cấp, với kích thước 0.5 mm phổ biến cho mọi tác vụ hiện nay phù hợp với nhiều đối tượng sử dụng như học sinh, sinh viên, dân văn phòng…sử dụng vào học tập, ghi chép,… - Dung tích lượng mực lớn, có thể viết lên tới 800m.', N'Bút Gel 0.5 mm - Deli C6600S-TI - Mực Tím - Bút thường sử dụng để viết ghi chú, soạn thảo văn bản trên giấy. - Bút gel Deli, nhiều màu sắc cho bạn lựa chọn - Nét bút mượt mà, màu sắc tươi sáng - Phù hợp với người đi làm, học sinh, sinh viên. - Bút có đầu bi sử dụng vật liệu cao cấp, với kích thước 0.5 mm phổ biến cho mọi tác vụ hiện nay phù hợp với nhiều đối tượng sử dụng như học sinh, sinh viên, dân văn phòng…sử dụng vào học tập, ghi chép,… - Dung tích lượng mực lớn, có thể viết lên tới 800m.', N'images/catalog/adcbook/ADC85359253_01.webp', 1, CONVERT(datetime2, N'2026-11-03T09:23:40.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (54, N'A85359252', N'Bút Gel Bấm EG575-BL Siêu Trơn 0.5-Xanh 12c/Hộp (Deli)', N'Bút Gel Bấm EG575-BL Siêu Trơn 0.5-Xanh 12c/Hộp (Deli)', N'Deli', N'but-viet', N'blue', 170000.00, 1, N'Bút Gel Bấm Siêu Trơn 0.5 mm - Deli EG575-BL - Mực Xanh Mực gel siêu trơn: Bút được trang bị mực gel chất lượng cao, đảm bảo viết mượt mà, không bị tắc nghẽn, giúp bạn dễ dàng ghi chú hoặc viết lách mà không gặp khó khăn. Ngòi 0.5mm chính xác: Với kích thước ngòi bút 0.5mm, bút đem đến cho bạn những nét chữ nhỏ gọn và sắc nét. Đây là lựa chọn lý tưởng để viết các tài liệu chi tiết, phác thảo hoặc ghi chú nhanh. Thiết kế tiện dụng: Bút được làm từ chất liệu nhựa bền, chắc chắn nhưng vẫn nhẹ nhàng', N'Bút Gel Bấm Siêu Trơn 0.5 mm - Deli EG575-BL - Mực Xanh Mực gel siêu trơn: Bút được trang bị mực gel chất lượng cao, đảm bảo viết mượt mà, không bị tắc nghẽn, giúp bạn dễ dàng ghi chú hoặc viết lách mà không gặp khó khăn. Ngòi 0.5mm chính xác: Với kích thước ngòi bút 0.5mm, bút đem đến cho bạn những nét chữ nhỏ gọn và sắc nét. Đây là lựa chọn lý tưởng để viết các tài liệu chi tiết, phác thảo hoặc ghi chú nhanh. Thiết kế tiện dụng: Bút được làm từ chất liệu nhựa bền, chắc chắn nhưng vẫn nhẹ nhàng', N'images/catalog/adcbook/ADC85359252_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:40.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (55, N'A85359251', N'Bút Gel Bấm 0.5mm EG118-RD - Đỏ 12c/Hộp (Deli)', N'Bút Gel Bấm 0.5mm EG118-RD - Đỏ 12c/Hộp (Deli)', N'Deli', N'but-viet', N'red', 120000.00, 1, N'Bút Gel 0.5 mm - Deli EG118-RD - Mực Đỏ - Bút thường sử dụng để viết ghi chú, soạn thảo văn bản trên giấy. - Bút gel Deli, nhiều màu sắc cho bạn lựa chọn - Nét bút mượt mà, màu sắc tươi sáng - Phù hợp với người đi làm, học sinh, sinh viên. - Bút có đầu bi sử dụng vật liệu cao cấp, với kích thước 0.5 mm phổ biến cho mọi tác vụ hiện nay phù hợp với nhiều đối tượng sử dụng như học sinh, sinh viên, dân văn phòng…sử dụng vào học tập, ghi chép,…', N'Bút Gel 0.5 mm - Deli EG118-RD - Mực Đỏ - Bút thường sử dụng để viết ghi chú, soạn thảo văn bản trên giấy. - Bút gel Deli, nhiều màu sắc cho bạn lựa chọn - Nét bút mượt mà, màu sắc tươi sáng - Phù hợp với người đi làm, học sinh, sinh viên. - Bút có đầu bi sử dụng vật liệu cao cấp, với kích thước 0.5 mm phổ biến cho mọi tác vụ hiện nay phù hợp với nhiều đối tượng sử dụng như học sinh, sinh viên, dân văn phòng…sử dụng vào học tập, ghi chép,…', N'images/catalog/adcbook/ADC85359251_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:40.000000', 126));
