    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (66, N'A88225232', N'Balo Chống Gù SAKOS Tiểu Học Kid Jolly - Dành Cho Học Sinh Cấp 1', N'Balo Chống Gù SAKOS Tiểu Học Kid Jolly - Dành Cho Học Sinh Cấp 1', N'Sakos', N'do-ban', N'multicolor', 615000.00, 1, N'Balo trẻ em Sakos Kid Jolly: Cùng bé đến trường học vui, trải nghiệm tuổi thơ diệu kỳ Ba mẹ luôn dành tặng những điều tuyệt vời và an toàn nhất cho con yêu của mình. Làm thế nào để bé luôn trong trạng thái khỏe mạnh, vui tươi và yêu thích việc học tập mỗi khi đến trường, đây chắc hẳn là mối quan tâm hàng đầu của các bậc phụ huynh. Sakos Kid Jolly là dòng ba lô học sinh tiểu học sở hữu những phẩm chất phù hợp với thể trạng và sức khỏe của các bạn nhỏ: Siêu nhẹ, chống gù, bảo vệ cột sống hiệu quả ', N'Balo trẻ em Sakos Kid Jolly: Cùng bé đến trường học vui, trải nghiệm tuổi thơ diệu kỳ Ba mẹ luôn dành tặng những điều tuyệt vời và an toàn nhất cho con yêu của mình. Làm thế nào để bé luôn trong trạng thái khỏe mạnh, vui tươi và yêu thích việc học tập mỗi khi đến trường, đây chắc hẳn là mối quan tâm hàng đầu của các bậc phụ huynh. Sakos Kid Jolly là dòng ba lô học sinh tiểu học sở hữu những phẩm chất phù hợp với thể trạng và sức khỏe của các bạn nhỏ: Siêu nhẹ, chống gù, bảo vệ cột sống hiệu quả ', N'images/catalog/adcbook/ADC88225232_01.webp', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (67, N'A88222636', N'Balo Chống Gù SAKOS Tiểu Học Stargo Wiggy - Dành Cho Học Sinh Cấp 1', N'Balo Chống Gù SAKOS Tiểu Học Stargo Wiggy - Dành Cho Học Sinh Cấp 1', N'Stargo', N'do-ban', N'multicolor', 485000.00, 1, N'Balo học sinh Stargo Wiggy: Nhẹ nhàng đến lớp, bền bỉ mỗi ngày Balo học sinh Stargo Wiggy là lựa chọn phù hợp cho các bạn học sinh cần một chiếc balo gọn nhẹ, tiện dụng và đủ bền để đồng hành trong suốt ngày dài học tập. Với thiết kế trẻ trung, dễ sử dụng cùng khả năng chứa đồ linh hoạt, Wiggy giúp việc mang theo sách vở, dụng cụ học tập và các vật dụng cá nhân trở nên nhẹ nhàng hơn. Chỉ nặng 0,4 kg nhưng có thể chịu tải lên đến 10 kg, chiếc balo vẫn giữ được form dáng ổn định, hạn chế tình trạn', N'Balo học sinh Stargo Wiggy: Nhẹ nhàng đến lớp, bền bỉ mỗi ngày Balo học sinh Stargo Wiggy là lựa chọn phù hợp cho các bạn học sinh cần một chiếc balo gọn nhẹ, tiện dụng và đủ bền để đồng hành trong suốt ngày dài học tập. Với thiết kế trẻ trung, dễ sử dụng cùng khả năng chứa đồ linh hoạt, Wiggy giúp việc mang theo sách vở, dụng cụ học tập và các vật dụng cá nhân trở nên nhẹ nhàng hơn. Chỉ nặng 0,4 kg nhưng có thể chịu tải lên đến 10 kg, chiếc balo vẫn giữ được form dáng ổn định, hạn chế tình trạn', N'images/catalog/adcbook/ADC88222636_01.png', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
