    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (72, N'A83652113', N'Balo Chống Gù Học Sinh Cấp 1 - Thỏ Tím SUN EIGHT - 22222', N'Balo Chống Gù Học Sinh Cấp 1 - Thỏ Tím SUN EIGHT - 22222', N'Sun Eight', N'do-ban', N'multicolor', 635000.00, 1, N'Balo Tiểu Học SUN EIGHT 22222 – Cặp Chống Gù, Nhẹ Vai, Chống Nước Cho Bé Cấp 1 - Chất liệu: Vải polyester chống co giãn, chống nhăn tốt - Sản phẩm của SUN EIGHT - Kích thước: 42x29.5x14.5cm Balo học sinh SUN EIGHT 22222 mang đến sự thoải mái và tiện lợi cho bé trong suốt năm học. Với trọng lượng siêu nhẹ, thiết kế lưng đệm chống cong vẹo và chất liệu kháng nước, sản phẩm giúp bé yên tâm đến trường mỗi ngày. Ngăn chứa rộng, chia ngăn hợp lý giúp sắp xếp sách vở và đồ dùng học tập dễ dàng. Quai đe', N'Balo Tiểu Học SUN EIGHT 22222 – Cặp Chống Gù, Nhẹ Vai, Chống Nước Cho Bé Cấp 1 - Chất liệu: Vải polyester chống co giãn, chống nhăn tốt - Sản phẩm của SUN EIGHT - Kích thước: 42x29.5x14.5cm Balo học sinh SUN EIGHT 22222 mang đến sự thoải mái và tiện lợi cho bé trong suốt năm học. Với trọng lượng siêu nhẹ, thiết kế lưng đệm chống cong vẹo và chất liệu kháng nước, sản phẩm giúp bé yên tâm đến trường mỗi ngày. Ngăn chứa rộng, chia ngăn hợp lý giúp sắp xếp sách vở và đồ dùng học tập dễ dàng. Quai đe', N'images/catalog/adcbook/ADC83652113_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (73, N'A83387223', N'Balo Demon Slayer BP-034/DS Nezuko/T24 (TL)', N'Balo Demon Slayer BP-034/DS Nezuko/T24 (TL)', N'Thiên Long', N'do-ban', N'multicolor', 405000.00, 1, N'🔹TÍNH NĂNG SẢN PHẨM ▪️Ba lô toàn diện với đệm mút dày êm giúp chống xô lệch, quai đeo trợ lực, đệm lưng thoát khí, nút điều chỉnh độ dài dây đeo, dây cài ngực. ▪️ Có thể điều chỉnh dây đeo phù hợp với từng bé. ▪️ Cặp mở được 360 độ vệ sinh dễ dàng. ▪️ Chống bụi nấm mốc, chống nước nhẹ và chống thấm. 🔹THÔNG SỐ KỸ THUẬT ▪️ Xuất xứ: Việt Nam. ▪️ Kích thước: 42 x 30 x 16 cm (dài x ngang x rộng). ▪️ Trọng lượng: 810g ▪️ Tải trọng: tối đa 8kg. 🔹HƯỚNG DẪN SỬ DỤNG VÀ BẢO QUẢN ▪️ Hướng dẫn sử dụng: Đe', N'🔹TÍNH NĂNG SẢN PHẨM ▪️Ba lô toàn diện với đệm mút dày êm giúp chống xô lệch, quai đeo trợ lực, đệm lưng thoát khí, nút điều chỉnh độ dài dây đeo, dây cài ngực. ▪️ Có thể điều chỉnh dây đeo phù hợp với từng bé. ▪️ Cặp mở được 360 độ vệ sinh dễ dàng. ▪️ Chống bụi nấm mốc, chống nước nhẹ và chống thấm. 🔹THÔNG SỐ KỸ THUẬT ▪️ Xuất xứ: Việt Nam. ▪️ Kích thước: 42 x 30 x 16 cm (dài x ngang x rộng). ▪️ Trọng lượng: 810g ▪️ Tải trọng: tối đa 8kg. 🔹HƯỚNG DẪN SỬ DỤNG VÀ BẢO QUẢN ▪️ Hướng dẫn sử dụng: Đe', N'images/catalog/adcbook/ADC83387223_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (74, N'A83386271', N'Cặp Chống Gù BP-025 Hồng/T24 (TL)', N'Cặp Chống Gù BP-025 Hồng/T24 (TL)', N'Thiên Long', N'do-ban', N'pink', 470000.00, 1, N'Cặp Chống Gù Glubby - Thiên Long BP-025/T24 - Màu Hồng Sản phẩm Cặp Chống Gù cao cấp Thiên Long có hệ thống chống gù toàn diện, thiết kế mặt sau với nhiều cải tiến như: quai đeo trợ lực, đệm mút dày dặn hơn… Kết hợp với chất liệu siêu nhẹ và bền, giúp bé thoải mái và dễ dàng di chuyển. Thiết kế 360 độ tiện lợi khi vệ sinh. Tính Năng Sản Phẩm: - Chống gù toàn diện với đệm mút dày êm giúp chống xô lệch, quai đeo trợ lực, đệm lưng thoát khí, nút điều chỉnh độ dài dây đeo, dây cài ngực. - Có thể điề', N'Cặp Chống Gù Glubby - Thiên Long BP-025/T24 - Màu Hồng Sản phẩm Cặp Chống Gù cao cấp Thiên Long có hệ thống chống gù toàn diện, thiết kế mặt sau với nhiều cải tiến như: quai đeo trợ lực, đệm mút dày dặn hơn… Kết hợp với chất liệu siêu nhẹ và bền, giúp bé thoải mái và dễ dàng di chuyển. Thiết kế 360 độ tiện lợi khi vệ sinh. Tính Năng Sản Phẩm: - Chống gù toàn diện với đệm mút dày êm giúp chống xô lệch, quai đeo trợ lực, đệm lưng thoát khí, nút điều chỉnh độ dài dây đeo, dây cài ngực. - Có thể điề', N'images/catalog/adcbook/ADC83386271_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
