    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (85, N'A82916028', N'Máy Tính Casio FX-580VNX (Trắng Đen)', N'Máy Tính Casio FX-580VNX (Trắng Đen)', N'Casio', N'luu-tru', N'black', 720000.00, 1, N'Máy Tính Casio FX580VNX 1. MÔ TẢ SẢN PHẨM Máy Tính Casio FX580VN X-BU thuộc dòng máy tính khoa học ClassWiz, được hãng máy tính Casio Nhật Bản sản xuất dành riêng cho nền giáo dục Việt. Sản phẩm tích hợp tới 521 tính năng, trong đó có rất nhiều tính năng mà các dòng máy tính khoa học trên thị trường hiện nay không có được. Casio fx-580VN X được phép đưa vào phòng thi Với mong muốn có một máy tính cầm tay phù hợp với học sinh, sinh viên Việt Nam, Casio đã cho ra đời fx-580VN X sau một thời gian d', N'Máy Tính Casio FX580VNX 1. MÔ TẢ SẢN PHẨM Máy Tính Casio FX580VN X-BU thuộc dòng máy tính khoa học ClassWiz, được hãng máy tính Casio Nhật Bản sản xuất dành riêng cho nền giáo dục Việt. Sản phẩm tích hợp tới 521 tính năng, trong đó có rất nhiều tính năng mà các dòng máy tính khoa học trên thị trường hiện nay không có được. Casio fx-580VN X được phép đưa vào phòng thi Với mong muốn có một máy tính cầm tay phù hợp với học sinh, sinh viên Việt Nam, Casio đã cho ra đời fx-580VN X sau một thời gian d', N'images/catalog/adcbook/ADC82916028_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (86, N'A82916027', N'Máy Tính CASIO FX880BTG (Màu Đen)', N'Máy Tính CASIO FX880BTG (Màu Đen)', N'Casio', N'luu-tru', N'black', 480000.00, 1, N'Máy tính CASIO FX880BTG 1. MÔ TẢ SẢN PHẨM Máy tính CASIO FX880BTG thuộc dòng máy tính khoa học ClassWiz của hãng máy tính CASIO. Và loại máy tính bỏ túi FX-880BTG đã ra đời với nhiều cải tiến về: thiết kế - giao diện, tính năng nổi trội và độ chính xác cao… để đáp ứng thực tiễn dạy và học tại Việt Nam, đồng thời thay đổi tư duy học tập lâu nay của học sinh. QR Code hỗ trợ dạy và học Bảng tính spreadsheet Hộp toán học Math Box Bảng nguyên tử khối Kiểm chứng Gian diện mới với thao tác đơn giản hơn', N'Máy tính CASIO FX880BTG 1. MÔ TẢ SẢN PHẨM Máy tính CASIO FX880BTG thuộc dòng máy tính khoa học ClassWiz của hãng máy tính CASIO. Và loại máy tính bỏ túi FX-880BTG đã ra đời với nhiều cải tiến về: thiết kế - giao diện, tính năng nổi trội và độ chính xác cao… để đáp ứng thực tiễn dạy và học tại Việt Nam, đồng thời thay đổi tư duy học tập lâu nay của học sinh. QR Code hỗ trợ dạy và học Bảng tính spreadsheet Hộp toán học Math Box Bảng nguyên tử khối Kiểm chứng Gian diện mới với thao tác đơn giản hơn', N'images/catalog/adcbook/ADC82916027_01.png', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (87, N'A76899009', N'Balo Chống Gù Học Sinh Cấp 1 - Gấu Xanh, Cam SUN EIGHT - 22222', N'Balo Chống Gù Học Sinh Cấp 1 - Gấu Xanh, Cam SUN EIGHT - 22222', N'Sun Eight', N'do-ban', N'multicolor', 635000.00, 1, N'Balo Tiểu Học SUN EIGHT 22222 – Cặp Chống Gù, Nhẹ Vai, Chống Nước Cho Bé Cấp 1 - Chất liệu: Vải polyester chống co giãn, chống nhăn tốt - Sản phẩm của SUN EIGHT - Kích thước: 42x29.5x14.5cm Balo học sinh SUN EIGHT 22222 mang đến sự thoải mái và tiện lợi cho bé trong suốt năm học. Với trọng lượng siêu nhẹ, thiết kế lưng đệm chống cong vẹo và chất liệu kháng nước, sản phẩm giúp bé yên tâm đến trường mỗi ngày. Ngăn chứa rộng, chia ngăn hợp lý giúp sắp xếp sách vở và đồ dùng học tập dễ dàng. Quai đe', N'Balo Tiểu Học SUN EIGHT 22222 – Cặp Chống Gù, Nhẹ Vai, Chống Nước Cho Bé Cấp 1 - Chất liệu: Vải polyester chống co giãn, chống nhăn tốt - Sản phẩm của SUN EIGHT - Kích thước: 42x29.5x14.5cm Balo học sinh SUN EIGHT 22222 mang đến sự thoải mái và tiện lợi cho bé trong suốt năm học. Với trọng lượng siêu nhẹ, thiết kế lưng đệm chống cong vẹo và chất liệu kháng nước, sản phẩm giúp bé yên tâm đến trường mỗi ngày. Ngăn chứa rộng, chia ngăn hợp lý giúp sắp xếp sách vở và đồ dùng học tập dễ dàng. Quai đe', N'images/catalog/adcbook/ADC76899009_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (88, N'A65411391', N'Lịch Bàn ADCBook 2026 - Hoan Ca', N'Lịch Bàn ADCBook 2026 - Hoan Ca', N'ADC', N'do-ban', N'multicolor', 125100.00, 1, N'HOAN CA với hình ảnh gia đình, các loài hoa và những điểm chạm về Ngựa được kết hợp tinh tế, tạo nên sắc thái hân hoan và viên mãn cho năm mới. HOAN CA mang đậm nét văn hoá Việt, với thiết kế mềm mại, tinh tế và vô cùng ấm áp.', N'HOAN CA với hình ảnh gia đình, các loài hoa và những điểm chạm về Ngựa được kết hợp tinh tế, tạo nên sắc thái hân hoan và viên mãn cho năm mới. HOAN CA mang đậm nét văn hoá Việt, với thiết kế mềm mại, tinh tế và vô cùng ấm áp.', N'images/catalog/adcbook/ADC65411391_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (89, N'A65411291', N'Lịch Bàn ADCBook 2026 - Hí Ca', N'Lịch Bàn ADCBook 2026 - Hí Ca', N'ADC', N'do-ban', N'multicolor', 125100.00, 1, N'HÍ CA: Với phong cách minh hoạ ngựa nhân hoá vô cùng dí dỏm, bộ lịch HÍ CA là một hành trình vui tươi, đầy động lực và may mắn. 12 tháng là 12 trải nghiệm thú vị, mang đến tiếng cười và cảm hứng cho từng ngày. HÍ CA là một bộ lịch vừa để theo dõi thời gian – vừa để chống stress!', N'HÍ CA: Với phong cách minh hoạ ngựa nhân hoá vô cùng dí dỏm, bộ lịch HÍ CA là một hành trình vui tươi, đầy động lực và may mắn. 12 tháng là 12 trải nghiệm thú vị, mang đến tiếng cười và cảm hứng cho từng ngày. HÍ CA là một bộ lịch vừa để theo dõi thời gian – vừa để chống stress!', N'images/catalog/adcbook/ADC65411291_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (90, N'A46337710', N'Bút Sáp Dầu 12 Màu + Chuốt Faber-Castell 120063ON (12 Màu/hộp)', N'Bút Sáp Dầu 12 Màu + Chuốt Faber-Castell 120063ON (12 Màu/hộp)', N'Faber-Castell', N'but-viet', N'multicolor', 81000.00, 1, N'Sáp màu dầu *Không độc hại-sử dụng màu thực phẩm-an toàn cho người dùng. *Thân bút bọc bằng giấy giúp tay cầm bút không dính bẩn và giữ bút khó bị gãy. *Đường kính 11mm giúp dễ nắm; Lý tưởng cho trẻ em. *Màu sắc sống động, tươi sáng, dễ phối màu. *Kèm sách hướng dẫn mô tả, hướng dẫn về màu sắc. *Dễ dàng giặt sạch vết mực bẩn trên quần áo. *Kèm dụng cụ chuốt và nối dài bút. *An toàn cho trẻ em.', N'Sáp màu dầu *Không độc hại-sử dụng màu thực phẩm-an toàn cho người dùng. *Thân bút bọc bằng giấy giúp tay cầm bút không dính bẩn và giữ bút khó bị gãy. *Đường kính 11mm giúp dễ nắm; Lý tưởng cho trẻ em. *Màu sắc sống động, tươi sáng, dễ phối màu. *Kèm sách hướng dẫn mô tả, hướng dẫn về màu sắc. *Dễ dàng giặt sạch vết mực bẩn trên quần áo. *Kèm dụng cụ chuốt và nối dài bút. *An toàn cho trẻ em.', N'images/catalog/adcbook/ADC46337710_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (91, N'A46337681', N'Bút Sáp Màu Có Thể Tẩy Được 12 Màu', N'Bút Sáp Màu Có Thể Tẩy Được 12 Màu', N'Faber-Castell', N'but-viet', N'multicolor', 90000.00, 1, N'Bút sáp màu dễ tẩy Faber-Castell cho bề mặt tô màu rực rỡ *Không độc hại *Dễ dàng giặt sạch vết bẩn mực trên quần áo *Màu sắc tươi sáng, độ phủ màu hoàn hảo. *Có thể sử dụng kỹ thuật phối màu, chuyển màu, kỹ thuật chuyển màu và kỹ thuật tẩy màu. *Tặng kèm gôm grip và chuốt. *An toàn cho trẻ em.', N'Bút sáp màu dễ tẩy Faber-Castell cho bề mặt tô màu rực rỡ *Không độc hại *Dễ dàng giặt sạch vết bẩn mực trên quần áo *Màu sắc tươi sáng, độ phủ màu hoàn hảo. *Có thể sử dụng kỹ thuật phối màu, chuyển màu, kỹ thuật chuyển màu và kỹ thuật tẩy màu. *Tặng kèm gôm grip và chuốt. *An toàn cho trẻ em.', N'images/catalog/adcbook/ADC46337681_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (92, N'A46337580', N'Bút Chì Staedtler 48 Màu 136C48', N'Bút Chì Staedtler 48 Màu 136C48', N'Staedtler', N'but-viet', N'multicolor', 199000.00, 1, N'Bút chì màu Steadtler Luna 136 C48 được sản xuất từ các nguyên liệu chất lượng đảm bảo an toàn khi sử dụng. Ngòi bút rất mềm mại, dễ tô màu trên các chất liệu và lâu mòn, giúp tiết kiệm chi phí khi sử dụng. Hộp sản phẩm gồm 48 chiếc bút với 48 màu khác nhau, đáp ứng được nhu cầu tô màu của bạn. Các màu sắc mịn màng, gần giống với màu thực tế, đem đến vẻ đẹp và sự sinh động cho các bức tranh. Bút chì rất dễ gọt, có độ bền cao, khó bị gãy khi tô màu hoặc khi bị rơi. Đặc biệt, các nét chì rất sắc n', N'Bút chì màu Steadtler Luna 136 C48 được sản xuất từ các nguyên liệu chất lượng đảm bảo an toàn khi sử dụng. Ngòi bút rất mềm mại, dễ tô màu trên các chất liệu và lâu mòn, giúp tiết kiệm chi phí khi sử dụng. Hộp sản phẩm gồm 48 chiếc bút với 48 màu khác nhau, đáp ứng được nhu cầu tô màu của bạn. Các màu sắc mịn màng, gần giống với màu thực tế, đem đến vẻ đẹp và sự sinh động cho các bức tranh. Bút chì rất dễ gọt, có độ bền cao, khó bị gãy khi tô màu hoặc khi bị rơi. Đặc biệt, các nét chì rất sắc n', N'images/catalog/adcbook/ADC46337580_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (93, N'A46337520', N'Màu Vẽ Acrylic-12 Tuýp Màu 572312 Faber Castell', N'Màu Vẽ Acrylic-12 Tuýp Màu 572312 Faber Castell', N'Faber-Castell', N'do-ban', N'multicolor', 212000.00, 1, N'Màu Vẽ Acrylic-12 Tuýp Màu 572312 Faber Castell Màu Vẽ Acrylic-12 Tuýp Màu 572312 Faber Castell được làm từ chất liệu cao cấp, không chứa chất độc hại. Với thành phần chính là màu acrylic, đây là loại màu vẽ có thể sử dụng được trên giấy, vải canvas với độ bền màu rất cao. Màu acrylic không gây độc hại, tuyệt đối an toàn cho trẻ nhỏ. - Chất liệu cao cấp, an toàn - Màu sắc tươi sáng, lâu phai, không thấm nước - Dạng tuýp tiện dụng và mới lạ', N'Màu Vẽ Acrylic-12 Tuýp Màu 572312 Faber Castell Màu Vẽ Acrylic-12 Tuýp Màu 572312 Faber Castell được làm từ chất liệu cao cấp, không chứa chất độc hại. Với thành phần chính là màu acrylic, đây là loại màu vẽ có thể sử dụng được trên giấy, vải canvas với độ bền màu rất cao. Màu acrylic không gây độc hại, tuyệt đối an toàn cho trẻ nhỏ. - Chất liệu cao cấp, an toàn - Màu sắc tươi sáng, lâu phai, không thấm nước - Dạng tuýp tiện dụng và mới lạ', N'images/catalog/adcbook/ADC46337520_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
