    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (97, N'A46333824', N'Ví Đựng Tiền Xu - Tiền Lẻ - Airpod Hoạt Hình Dễ Thương', N'Ví Đựng Tiền Xu - Tiền Lẻ - Airpod Hoạt Hình Dễ Thương', N'CÔNG TY CỔ PHẦN GIÁO DỤC BILI VIỆT NAM', N'do-ban', N'multicolor', 18000.00, 1, N'Ví Đựng Tiền Xu - Tiền Lẻ - Airpod Hoạt Hình Dễ Thương Phân loại: Văn phòng phẩm - Dụng cụ học sinh, phụ kiện học đường Chất liệu: Vải mềm, bền đẹp, thân thiện với người dùng Màu sắc: Nhiều màu sắc tươi sáng, dễ phối với các vật dụng khác Kích thước: 14 x 11 x 1 cm - nhỏ gọn, tiện lợi mang theo Trọng lượng: Chỉ 50g - nhẹ nhàng, dễ cầm nắm Độ tuổi khuyến nghị: Phù hợp cho trẻ em từ 3 tuổi trở lên Đặc điểm nổi bật: Thiết kế hoạt hình dễ thương: Kiểu dáng ngộ nghĩnh, đáng yêu, tạo điểm nhấn cá nhân', N'Ví Đựng Tiền Xu - Tiền Lẻ - Airpod Hoạt Hình Dễ Thương Phân loại: Văn phòng phẩm - Dụng cụ học sinh, phụ kiện học đường Chất liệu: Vải mềm, bền đẹp, thân thiện với người dùng Màu sắc: Nhiều màu sắc tươi sáng, dễ phối với các vật dụng khác Kích thước: 14 x 11 x 1 cm - nhỏ gọn, tiện lợi mang theo Trọng lượng: Chỉ 50g - nhẹ nhàng, dễ cầm nắm Độ tuổi khuyến nghị: Phù hợp cho trẻ em từ 3 tuổi trở lên Đặc điểm nổi bật: Thiết kế hoạt hình dễ thương: Kiểu dáng ngộ nghĩnh, đáng yêu, tạo điểm nhấn cá nhân', N'images/catalog/adcbook/ADC46333824_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (98, N'A46332781', N'Bút Dạ Kim Thiên Long FL-04/DO - Màu Tím', N'Bút Dạ Kim Thiên Long FL-04/DO - Màu Tím', N'Thiên Long', N'but-viet', N'purple', 10000.00, 1, N'Bút Lông Kim FL-04/DO - Mực Tím Đầu bi 0.3mm, bọc kim loại. Lượng mực viết dài 1200-1500m, không bị lem và đều Nét viết thanh mãnh nhỏ, trơn, êm Dáng bút thon gọn dễ cầm , xinh xắn thích hợp với trẻ em. Thân in hình Doraemon rất được các bạn trẻ yêu mến và sinh động tạo sự thích thú cho các em rèn luyện chữ viết', N'Bút Lông Kim FL-04/DO - Mực Tím Đầu bi 0.3mm, bọc kim loại. Lượng mực viết dài 1200-1500m, không bị lem và đều Nét viết thanh mãnh nhỏ, trơn, êm Dáng bút thon gọn dễ cầm , xinh xắn thích hợp với trẻ em. Thân in hình Doraemon rất được các bạn trẻ yêu mến và sinh động tạo sự thích thú cho các em rèn luyện chữ viết', N'images/catalog/adcbook/ADC46332781_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (99, N'A46214322', N'Mực Bút Dạ Dầu Pentel N450 NR401-A Màu Đen', N'Mực Bút Dạ Dầu Pentel N450 NR401-A Màu Đen', N'Pentel', N'but-viet', N'black', 25000.00, 1, N'Ưu điểm của sản phẩm: - Thể tích: 15ml - Sản phẩm có 3 màu: xanh, đen, đỏ - Mực sử dụng để đổ vào bút dạ dầu N450 - Sản phẩm có thể đổ tối đa 3 lần.', N'Ưu điểm của sản phẩm: - Thể tích: 15ml - Sản phẩm có 3 màu: xanh, đen, đỏ - Mực sử dụng để đổ vào bút dạ dầu N450 - Sản phẩm có thể đổ tối đa 3 lần.', N'images/catalog/adcbook/ADC46214322_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (100, N'A46332405', N'Vỉ 3 Bút Dạ Kim FL04/DO - Màu Tím', N'Vỉ 3 Bút Dạ Kim FL04/DO - Màu Tím', N'Thiên Long', N'but-viet', N'purple', 26000.00, 1, N'Vỉ 3 Bút Lông Kim FL-04/DO - Mực Tím Thông số kĩ thuật : Thương hiệu Thiên Long Đường kính viên bi 0.5mm Tính năng nổi bật: Bút có thiết kế đơn giản và hiện đại. Thân và nắp bút bằng nhựa trắng đục, tảm nhựa pha màu theo màu mực của ruột. Thân bút tròn và nhỏ rất phù hợp với tay cầm của HS. Mực cho màu đậm và tươi sáng, viết rất nhẹ và êm trơn. Đặc điểm bút : Đầu bi: 0.5mm,, sản suất tại Thụy Sĩ. Độ dài viết được: 500-1000m. Mực đạt chuẩn: ASTM D-4236, EN71/3. Lợi ích: Thiết kế bút hiện đại, đượ', N'Vỉ 3 Bút Lông Kim FL-04/DO - Mực Tím Thông số kĩ thuật : Thương hiệu Thiên Long Đường kính viên bi 0.5mm Tính năng nổi bật: Bút có thiết kế đơn giản và hiện đại. Thân và nắp bút bằng nhựa trắng đục, tảm nhựa pha màu theo màu mực của ruột. Thân bút tròn và nhỏ rất phù hợp với tay cầm của HS. Mực cho màu đậm và tươi sáng, viết rất nhẹ và êm trơn. Đặc điểm bút : Đầu bi: 0.5mm,, sản suất tại Thụy Sĩ. Độ dài viết được: 500-1000m. Mực đạt chuẩn: ASTM D-4236, EN71/3. Lợi ích: Thiết kế bút hiện đại, đượ', N'images/catalog/adcbook/ADC46332405_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[Products] ([ProductId], [ProductCode], [Name], [NameVi], [Brand], [Category], [Color], [Price], [Stock], [Description], [DescriptionVi], [ImagePath], [IsActive], [UpdatedAt]) VALUES (101, N'A46341102', N'Máy Tính Văn Phòng Canon AS-120 II', N'Máy Tính Văn Phòng Canon AS-120 II', N'Canon', N'do-ban', N'black', 190000.00, 1, N'Máy Tính Văn Phòng Canon AS-120 II 1. MÔ TẢ SẢN PHẨM Máy Tính Để Bàn Canon AS-120 II ASA HB, với thiết kế đế cong cùng màn hình LCD có độ phân giải cao giúp người dùng dễ dàng quan sát màn hình và sử dụng. Chất liệu kháng vân tay và mồ hôi cao cấp, các chức năng phù hợp sử dụng tính toán cho khối kinh doanh và khối văn phòng. Máy Tính Cầm Tay Canon AS-120 II ASA HB là công cụ tính toán hoàn hảo cho dân văn phòng và chủ cửa hàng. 2. THÔNG SỐ KỸ THUẬT Mã hàng: AS-120 II ASA HB Hiển thị: 12 số Màu ', N'Máy Tính Văn Phòng Canon AS-120 II 1. MÔ TẢ SẢN PHẨM Máy Tính Để Bàn Canon AS-120 II ASA HB, với thiết kế đế cong cùng màn hình LCD có độ phân giải cao giúp người dùng dễ dàng quan sát màn hình và sử dụng. Chất liệu kháng vân tay và mồ hôi cao cấp, các chức năng phù hợp sử dụng tính toán cho khối kinh doanh và khối văn phòng. Máy Tính Cầm Tay Canon AS-120 II ASA HB là công cụ tính toán hoàn hảo cho dân văn phòng và chủ cửa hàng. 2. THÔNG SỐ KỸ THUẬT Mã hàng: AS-120 II ASA HB Hiển thị: 12 số Màu ', N'images/catalog/adcbook/ADC46341102_01.jpg', 1, CONVERT(datetime2, N'2026-11-03T09:23:58.000000', 126));
    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (1, N'ADCBook Store', N'86356366', N'https://adcbook.net.vn/bo-ky-thuat-dien-lop-5-mic-2-dong-co-th', N'Bộ Kĩ Thuật Điện Lớp 5 Mic (2 Động Cơ)', N'Mic', N'Dụng Cụ Học Sinh Khác', N'do-ban', N'multicolor', N'Nhiều màu', 252000.00, 0, N'Bộ Kĩ Thuật Điện Lớp 5 Mic Gồm các vật liệu cần thiết để tạo nên một mạch điện đơn giản Bộ sản phẩm gồm nhiều mảnh vật liệu tạo thành một mạch điện đơn giản giúp cho bóng đèn phát sáng. Cấu tạo sản phẩm dễ dàng lắp ráp, giúp học sinh thực hành các bài học một cách nhanh chóng, hiệu quả. Sử dụng nguồn pin AA nên cực kỳ an toàn cho học sinh khi thực hành các bài tập về điện Bộ sản phẩm gồm: Pin 1.5V, bóng đèn 1.5V - 2.5V, 2 đoạn dây, một số mảnh vật liệu dẫn điện, cách điện Thiết kế hộp đựng tiện lợi có khóa gài chắc chắn.', N'https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-820l4-mdy11ez1xibl29-1.webp?v=1785206516417', N'images/ADC86356366_01.webp', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 86356366, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/bo-ky-thuat-dien-lop-5-mic-2-dong-co-th", "source_collection": "https://adcbook.net.vn/van-phong-pham", "scraped_at_utc": "2026-11-03T08:29:18.180814+00:00", "name_vi": "Bộ Kĩ Thuật Điện Lớp 5 Mic (2 Động Cơ)", "brand": "Mic", "vendor": "Công ty CP TBGD Minh Đức", "product_type": "Dụng Cụ Học Sinh Khác", "category": "do-ban", "color_vi": "Nhiều màu", "color": "multicolor", "material": "Nhựa", "dimensions": "", "origin": "Việt Nam", "price_vnd": 252000.0, "compare_at_price_vnd": 0, "available": false, "description_vi": "Bộ Kĩ Thuật Điện Lớp 5 Mic Gồ