    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (9, N'ADCBook Store', N'85982817', N'https://adcbook.net.vn/tui-1-cuc-f4-plus-89-v35-cb2636-mn', N'Túi 1 Cúc F4 Plus 89.V35 CB2636', N'Plus', N'File Đựng Hồ Sơ', N'luu-tru', N'white', N'Màu Trắng Trong', 7000.00, 0, N'Bìa Nút Trong F4 Plus (0.15mm) 89-V35 Sản phẩm được thiết kế như một bao thư cỡ lớn, có nắp kín và nút bấm chắc chắn giúp giữ cho tài liệu luôn nằm gọn bên trong, tránh thất lạc. Bìa được làm từ nhựa cao cấp, chống thấm nước, chống bám bụi, bảo quản an toàn cho giấy tờ của bạn. Sản phẩm có thể lưu trữ được các hồ sơ, giấy tờ ở kích cỡ A4. Bìa có màu sắc trong suốt giúp bạn dễ quan sát giấy tờ bên trong, tiện lợi khi tìm kiếm. Sản phẩm không thể thiếu của giới học sinh, sinh viên và nhân viên văn phòng.', N'https://bizweb.dktcdn.net/100/567/082/products/image-195509-1-32989-1.jpg?v=1784533845307', N'images/ADC85982817_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 85982817, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/tui-1-cuc-f4-plus-89-v35-cb2636-mn", "source_collection": "https://adcbook.net.vn/van-phong-pham", "scraped_at_utc": "2026-11-03T08:29:18.180814+00:00", "name_vi": "Túi 1 Cúc F4 Plus 89.V35 CB2636", "brand": "Plus", "vendor": "Plus", "product_type": "File Đựng Hồ Sơ", "category": "luu-tru", "color_vi": "Màu Trắng Trong", "color": "white", "material": "Nhựa", "dimensions": "35 x 26 cm", "origin": "Nhật Bản", "price_vnd": 7000.0, "compare_at_price_vnd": 0, "available": false, "description_vi": "Bìa Nút Trong F4 Plus (0.15mm) 89-V35 Sản phẩm được thiết kế như một bao thư cỡ lớn, có nắp kín và nút bấm chắc chắn giúp giữ cho tài liệu luôn nằm gọn bên trong, tránh thất lạc. Bìa được làm từ nhựa cao cấp, chống thấm nước, chống bám bụi, bảo quản an toàn cho giấy tờ của bạn. Sản phẩm có thể lưu trữ được các hồ sơ, giấy tờ ở kích cỡ A4. Bìa có màu sắc trong suốt giúp bạn dễ quan sát giấy tờ bên trong, tiện lợi khi tìm kiếm. Sản phẩm không thể thiếu của giới học sinh, sinh viên và nhân viên văn phòng.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/image-195509-1-32989-1.jpg?v=1784533845307", "https://bizweb.dktcdn.net/100/567/082/products/8936007454602-1.jpg?v=1784533858270"], "local_images": ["images/ADC85982817_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T08:29:18.000000', 126), CONVERT(datetime2, N'2026-11-03T08:33:08.000000', 126));
    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (10, N'ADCBook Store', N'85973959', N'https://adcbook.net.vn/bia-cong-a4-5cm-lanrch-800-v017-mau-xanh-duong-new-version-mn', N'Bìa Còng A4 5cm Lanrch 800-V017 Xanh Dương', N'Plus', N'File Đựng Hồ Sơ', N'luu-tru', N'blue', N'Xanh Dương', 67000.00, 0, N'Bìa Còng A4 Plus 5cm 800-V017 - Màu Xanh Dương Sản phẩm được làm từ carton cứng, có độ bền cao, chịu va đập tốt. Sản phẩm không thấm nước, dễ dàng làm sạch lau chùi, giúp sắp xếp tài liệu dễ dàng. Khóa còng là kim loại phủ niken sáng bóng, chống gỉ sét, chống bám bụi, có thể đóng mở nhiều lần để thêm bớt tài liệu mà không bị cong vênh. Sản phẩm có kích cỡ bằng khổ giấy A4, phù hợp với đa số các loại giấy tờ hiện nay, là sản phẩm lý tưởng để lưu trữ hồ sơ, giấy tờ quan trọng không bị nhăn, nhàu. Gáy hộp rộng 5cm, có thể đựng được khối lượng lớn giấy tờ. Là vật dụng thiết yếu trong văn phòng giúp bạn lưu giữ hồ sơ gọn gàng và cẩn thận, đảm bảo giấy tờ không bị nhàu nát hay rơi rớt, mang lại hiệu quả sử dụng cao trong bảo quản tài liệu.', N'https://bizweb.dktcdn.net/100/567/082/products/8936007452950-1.jpg?v=1784530855583', N'images/ADC85973959_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 85973959, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/bia-cong-a4-5cm-lanrch-800-v017-mau-xanh-duong-new-version-mn", "source_collection": "https://adcbook.net.vn/van-phong-pham", "scraped_at_utc": "2026-11-03T08:29:18.180814+00:00", "name_vi": "Bìa Còng A4 5cm Lanrch 800-V017 Xanh Dương", "brand": "Plus", "vendor": "Plus", "product_type": "File Đựng Hồ Sơ", "category": "luu-tru", "color_vi": "Xanh Dương", "color": "blue", "material": "Kim Loại", "dimensions": "28 x 32 x 5 cm", "origin": "Nhật Bản", "price_vnd": 67000.0, "compare_at_price_vnd": 0, "available": false, "description_vi": "Bìa Còng A4 Plus 5cm 800-V017 - Màu Xanh Dương Sản phẩm được làm từ carton cứng, có độ bền cao, chịu va đập tốt. Sản phẩm không thấm nước, dễ dàng làm sạch lau chùi, giúp sắp xếp tài liệu dễ dàng. Khóa còng là kim loại phủ niken sáng bóng, chống gỉ sét, chống bám bụi, có thể đóng mở nhiều lần để thêm bớt tài liệu mà không bị cong vênh. Sản phẩm có kích cỡ bằng khổ giấy A4, phù hợp với đa số các loại giấy tờ hiện nay, là sản phẩm lý tưởng để lưu trữ hồ sơ, giấy tờ quan trọng không bị nhăn, nhàu. Gáy hộp rộng 5cm, có thể đựng được khối lượng lớn giấy tờ. Là vật dụng thiết yếu trong văn phòng giúp bạn lưu giữ hồ sơ gọn gàng và cẩn thận, đảm bảo giấy tờ không bị nhàu nát hay rơi rớt, mang lại hiệu quả sử dụng cao trong bảo quản tài liệu.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/8936007452950-1.jpg?v=1784530855583"], "local_images": ["images/ADC85973959_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T08:29:18.000000', 126), CONVERT(datetime2, N'2026-11-03T08:33:08.000000', 126));
