    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (17, N'ADCBook Store', N'64543899', N'https://adcbook.net.vn/keo-van-phong-em600-mau-lan-deli', N'Kéo Văn Phòng EM600 Nhiều Màu (Deli)', N'Deli', N'Kéo Văn Phòng', N'dung-cu', N'multicolor', N'Nhiều màu', 28000.00, 0, N'Kéo Văn Phòng Deli EM600 thiết kế mũi kéo nhọn, dài và sắc bén cho phép bạn cắt các loại giấy, vải hoặc bìa thật dễ dàng trong thời gian ngắn. Kéo có màu nâu và đen tinh tế, đẹp mắt cho bạn lựa chọn. Kéo được bọc thêm lớp nhựa ở cán, tạo cảm giác êm ái và thoải mái cho bạn khi cắt. Lưỡi kéo làm từ hợp kim thép cao cấp Kéo Deli chế tác phần lưỡi cắt từ chất liệu hợp kim thép cao cấp có độ sắc bén hoàn hảo giúp bạn cắt giấy, vải,.. thật dễ dàng. Lưỡi kéo không gỉ sét nên bạn có thể yên tâm sử dụng lâu dài. Cán kéo bọc nhựa êm tay Kéo được bọc thêm lớp nhựa ở cán, tạo cảm giác êm ái và thoải mái cho bạn khi cắt. Thiết kế này cũng giúp tránh cho đôi tay của bạn không đụng trúng lưỡi kéo khi sử dụng, đảm bảo an toàn tối ưu hơn. Lưỡi kéo dài, màu sắc tinh tế Kéo Deli EM600 có kích thước 180mm giúp bạn thực hiện những đường cắt dài, rút ngắn thời gian đồng thời giữ cho vết cắt đều đẹp và chuẩn xác hơn. Giữa tay cầm có 2 gờ giữ cho kéo không bị khít lại khi bóp tay mạnh, giữ cho chuyển động kéo được liên tục, suôn sẻ hơn. Lỗ khoét ở tay cầm lớn nên không làm gò bó ngón tay khi chuyển động. Kéo có màu nâu và đen tinh tế, đẹp mắt cho bạn lựa chọn. Tiện sử dụng Kéo có thể dùng cắt giấy, bìa nhựa hoặc vải tùy theo mục đích sử dụng của học sinh, sinh viên và dân văn phòng.', N'https://bizweb.dktcdn.net/100/567/082/products/wlnvuu5zohdnss63hzgtzyraua0f.jpg?v=1785138902910', N'images/ADC64543899_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 64543899, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/keo-van-phong-em600-mau-lan-deli", "source_collection": "https://adcbook.net.vn/van-phong-pham", "scraped_at_utc": "2026-11-03T08:29:18.180814+00:00", "name_vi": "Kéo Văn Phòng EM600 Nhiều Màu (Deli)", "brand": "Deli", "vendor": "CÔNG TY TNHH PHÁT TRIỂN DELI VIỆT NAM (mã mới)", "product_type": "Kéo Văn Phòng", "category": "dung-cu", "color_vi": "Nhiều màu", "color": "multicolor", "material": "Hợp kim", "dimensions": "18 cm", "origin": "Trung Quốc", "price_vnd": 28000.0, "compare_at_price_vnd": 0, "available": false, "description_vi": "Kéo Văn Phòng Deli EM600 thiết kế mũi kéo nhọn, dài và sắc bén cho phép bạn cắt các loại giấy, vải hoặc bìa thật dễ dàng trong thời gian ngắn. Kéo có màu nâu và đen tinh tế, đẹp mắt cho bạn lựa chọn. Kéo được bọc thêm lớp nhựa ở cán, tạo cảm giác êm ái và thoải mái cho bạn khi cắt. Lưỡi kéo làm từ hợp kim thép cao cấp Kéo Deli chế tác phần lưỡi cắt từ chất liệu hợp kim thép cao cấp có độ sắc bén hoàn hảo giúp bạn cắt giấy, vải,.. thật dễ dàng. Lưỡi kéo không gỉ sét nên bạn có thể yên tâm sử dụng lâu dài. Cán kéo bọc nhựa êm tay Kéo được bọc thêm lớp nhựa ở cán, tạo cảm giác êm ái và thoải mái cho bạn khi cắt. Thiết kế này cũng giúp tránh cho đôi tay của bạn không đụng trúng lưỡi kéo khi sử dụng, đảm bảo an toàn tối ưu hơn. Lưỡi kéo dài, màu sắc tinh tế Kéo Deli EM600 có kích thước 180mm giúp bạn thực hiện những đường cắt dài, rút ngắn thời gian đồng thời giữ cho vết cắt đều đẹp và chuẩn xác hơn. Giữa tay cầm có 2 gờ giữ cho kéo không bị khít lại khi bóp tay mạnh, giữ cho chuyển động kéo được liên tục, suôn sẻ hơn. Lỗ khoét ở tay cầm lớn nên không làm gò bó ngón tay khi chuyển động. Kéo có màu nâu và đen tinh tế, đẹp mắt cho bạn lựa chọn. Tiện sử dụng Kéo có thể dùng cắt giấy, bìa nhựa hoặc vải tùy theo mục đích sử dụng của học sinh, sinh viên và dân văn phòng.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/wlnvuu5zohdnss63hzgtzyraua0f.jpg?v=1785138902910"], "local_images": ["images/ADC64543899_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T08:29:18.000000', 126), CONVERT(datetime2, N'2026-11-03T08:33:09.000000', 126));
