    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (38, N'ADCBook Store', N'52869227', N'https://adcbook.net.vn/bang-keo-silicon-da-nang-2-mat-12mm-3m-e685-1-250-tc', N'Băng Keo Silicon Đa Năng 2 Mặt E685 (12mm*3m)', N'Eras', N'Băng Dính - Cắt Băng Dính', N'do-ban', N'multicolor', N'Trong Suốt', 28000.00, 0, N'Băng Keo Silicon Đa Năng 2 Mặt Eras E685 Chính Hãng – Siêu Dính, Chống Nước, Dễ Sử Dụng Băng Keo Silicon Đa Năng 2 Mặt Eras E685 là dòng băng keo silicon trong suốt cao cấp có độ bám dính mạnh, chuyên dùng để cố định vật dụng, treo đồ, dán tường hoặc trang trí nội thất mà không cần khoan đục. Sản phẩm được nhiều gia đình, văn phòng và cửa hàng lựa chọn nhờ khả năng chống nước, dễ sử dụng và tính thẩm mỹ cao. * Ưu Điểm Nổi Bật Của Băng Keo Silicon Eras E685 - Siêu Dính – Bám Chắc Trên Nhiều Bề Mặt - Băng keo silicon Eras E685 bám tốt trên kính, gạch men, kim loại, gỗ, nhựa và nhiều bề mặt phẳng khác. Giúp cố định vật dụng chắc chắn và tiện lợi. * Chống Nước Hiệu Quả Chất liệu silicon cao cấp giúp sản phẩm chống nước tốt, phù hợp sử dụng tại nhà bếp, phòng tắm hoặc nơi có độ ẩm cao.', N'https://bizweb.dktcdn.net/100/567/082/products/2024-07-11-16-43-22-ps548f-percentage-20-1-1.jpg?v=1785204149837', N'images/ADC52869227_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 52869227, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/bang-keo-silicon-da-nang-2-mat-12mm-3m-e685-1-250-tc", "source_collection": "https://adcbook.net.vn/van-phong-pham", "scraped_at_utc": "2026-11-03T08:29:18.180814+00:00", "name_vi": "Băng Keo Silicon Đa Năng 2 Mặt E685 (12mm*3m)", "brand": "Eras", "vendor": "Công ty TNHH Thanh Chương", "product_type": "Băng Dính - Cắt Băng Dính", "category": "do-ban", "color_vi": "Trong Suốt", "color": "multicolor", "material": "", "dimensions": "12mm x 3m", "origin": "Trung Quốc", "price_vnd": 28000.0, "compare_at_price_vnd": 0, "available": false, "description_vi": "Băng Keo Silicon Đa Năng 2 Mặt Eras E685 Chính Hãng – Siêu Dính, Chống Nước, Dễ Sử Dụng Băng Keo Silicon Đa Năng 2 Mặt Eras E685 là dòng băng keo silicon trong suốt cao cấp có độ bám dính mạnh, chuyên dùng để cố định vật dụng, treo đồ, dán tường hoặc trang trí nội thất mà không cần khoan đục. Sản phẩm được nhiều gia đình, văn phòng và cửa hàng lựa chọn nhờ khả năng chống nước, dễ sử dụng và tính thẩm mỹ cao. * Ưu Điểm Nổi Bật Của Băng Keo Silicon Eras E685 - Siêu Dính – Bám Chắc Trên Nhiều Bề Mặt - Băng keo silicon Eras E685 bám tốt trên kính, gạch men, kim loại, gỗ, nhựa và nhiều bề mặt phẳng khác. Giúp cố định vật dụng chắc chắn và tiện lợi. * Chống Nước Hiệu Quả Chất liệu silicon cao cấp giúp sản phẩm chống nước tốt, phù hợp sử dụng tại nhà bếp, phòng tắm hoặc nơi có độ ẩm cao.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/2024-07-11-16-43-22-ps548f-percentage-20-1-1.jpg?v=1785204149837"], "local_images": ["images/ADC52869227_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T08:29:18.000000', 126), CONVERT(datetime2, N'2026-11-03T08:33:09.000000', 126));
