_vi": "Bút Gel 0.5 mm - Deli C6600S-TI - Mực Tím - Bút thường sử dụng để viết ghi chú, soạn thảo văn bản trên giấy. - Bút gel Deli, nhiều màu sắc cho bạn lựa chọn - Nét bút mượt mà, màu sắc tươi sáng - Phù hợp với người đi làm, học sinh, sinh viên. - Bút có đầu bi sử dụng vật liệu cao cấp, với kích thước 0.5 mm phổ biến cho mọi tác vụ hiện nay phù hợp với nhiều đối tượng sử dụng như học sinh, sinh viên, dân văn phòng…sử dụng vào học tập, ghi chép,… - Dung tích lượng mực lớn, có thể viết lên tới 800m.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/6921734954725-244c29ce-defa-43e6-abef-4fe9148adcc8.webp?v=1784705955677", "https://bizweb.dktcdn.net/100/567/082/products/6921734954725-97435dba-994a-42a2-a385-d7a4971e37e6.jpg?v=1784705955677", "https://bizweb.dktcdn.net/100/567/082/products/6921734954725-3-1.jpg?v=1784705955677", "https://bizweb.dktcdn.net/100/567/082/products/6921734954725-4-bf54e5fb-35a0-4a7d-931a-ae6c0b6e18bf.jpg?v=1784705955677"], "local_images": ["images/ADC85359253_01.webp"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T09:14:28.000000', 126), CONVERT(datetime2, N'2026-11-03T09:23:38.000000', 126));
    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (42, N'ADCBook Store', N'85359252', N'https://adcbook.net.vn/but-gel-bam-eg575-bl-sieu-tron-0-5-xanh-12c-h-12h-l-deli', N'Bút Gel Bấm EG575-BL Siêu Trơn 0.5-Xanh 12c/Hộp (Deli)', N'Deli', N'Bút Gel - Bút Nước - Ruột Bút Gel', N'but-viet', N'blue', N'Xanh', 170000.00, 1, N'Bút Gel Bấm Siêu Trơn 0.5 mm - Deli EG575-BL - Mực Xanh Mực gel siêu trơn: Bút được trang bị mực gel chất lượng cao, đảm bảo viết mượt mà, không bị tắc nghẽn, giúp bạn dễ dàng ghi chú hoặc viết lách mà không gặp khó khăn. Ngòi 0.5mm chính xác: Với kích thước ngòi bút 0.5mm, bút đem đến cho bạn những nét chữ nhỏ gọn và sắc nét. Đây là lựa chọn lý tưởng để viết các tài liệu chi tiết, phác thảo hoặc ghi chú nhanh. Thiết kế tiện dụng: Bút được làm từ chất liệu nhựa bền, chắc chắn nhưng vẫn nhẹ nhàng, dễ dàng cầm nắm trong thời gian dài mà không cảm thấy mỏi tay. Màu mực đen đậm nét: Mực đen sắc nét, bền màu giúp bạn dễ dàng đọc lại các ghi chú và văn bản. Bút rất thích hợp để sử dụng trong công việc, học tập hoặc làm quà tặng.', N'https://bizweb.dktcdn.net/100/567/082/products/6942233674181-11zon-1-jpeg.jpg?v=1784711478027', N'images/ADC85359252_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 85359252, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/but-gel-bam-eg575-bl-sieu-tron-0-5-xanh-12c-h-12h-l-deli", "source_collection": "https://adcbook.net.vn/but-viet", "scraped_at_utc": "2026-11-03T09:14:27.790835+00:00", "name_vi": "Bút Gel Bấm EG575-BL Siêu Trơn 0.5-Xanh 12c/Hộp (Deli)", "brand": "Deli", "vendor": "CÔNG TY TNHH PHÁT TRIỂN DELI VIỆT NAM (mã mới)", "product_type": "Bút Gel - Bút Nước - Ruột Bút Gel", "category": "but-viet", "color_vi": "Xanh", "color": "blue", "material": "Nhựa", "dimensions": "", "origin": "Trung Quốc", "price_vnd": 170000.0, "compare_at_price_vnd": 0, "available": true, "description_vi": "Bút Gel Bấm Siêu Trơn 0.5 mm - Deli EG575-BL - Mực Xanh Mực gel siêu trơn: Bút được trang bị mực gel chất lượng cao, đảm bảo viết mượt mà, không bị tắc nghẽn, giúp bạn dễ dàng ghi chú hoặc viết lách mà không gặp khó khăn. Ngòi 0.5mm chính xác: Với kích thước ngòi bút 0.5mm, bút đem đến cho bạn những nét chữ nhỏ gọn và sắc nét. Đây là lựa chọn lý tưởng để viết các tài liệu chi tiết, phác thảo hoặc ghi chú nhanh. Thiết kế tiện dụng: Bút được làm từ chất liệu nhựa bền, chắc chắn nhưng vẫn nhẹ nhàng, dễ dàng cầm nắm trong thời gian dài mà không cảm thấy mỏi tay. Màu mực đen đậm nét: Mực đen sắc nét, bền màu giúp bạn dễ dàng đọc lại các ghi chú và văn bản. Bút rất thích hợp để sử dụng trong công việc, học tập hoặc làm quà tặng.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/6942233674181-11zon-1-jpeg.jpg?v=1784711478027", "https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-7ras8-m4fvy5pt6zm792-1.webp?v=1784711478027", "https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-7ras8-m4fvy5pt5km82e.webp?v=1784711478027", "https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-7ras8-m4fvy5pt8e6n6b.webp?v=1784711478027", "https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-7ras8-m4fvy5pt8dr40f.webp?v=1784711478027"], "local_images": ["images/ADC85359252_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T09:14:28.000000', 126), CONVERT(datetime2, N'2026-11-03T09:23:38.000000', 126));
