    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (49, N'ADCBook Store', N'88225232', N'https://adcbook.net.vn/balo-chong-gu-sakos-tieu-hoc-kid-jolly-danh-cho-hoc-sinh-cap-1', N'Balo Chống Gù SAKOS Tiểu Học Kid Jolly - Dành Cho Học Sinh Cấp 1', N'Sakos', N'Cặp - Ba Lô Tiểu Học', N'do-ban', N'multicolor', N'Nhiều màu', 615000.00, 1, N'Balo trẻ em Sakos Kid Jolly: Cùng bé đến trường học vui, trải nghiệm tuổi thơ diệu kỳ Ba mẹ luôn dành tặng những điều tuyệt vời và an toàn nhất cho con yêu của mình. Làm thế nào để bé luôn trong trạng thái khỏe mạnh, vui tươi và yêu thích việc học tập mỗi khi đến trường, đây chắc hẳn là mối quan tâm hàng đầu của các bậc phụ huynh. Sakos Kid Jolly là dòng ba lô học sinh tiểu học sở hữu những phẩm chất phù hợp với thể trạng và sức khỏe của các bạn nhỏ: Siêu nhẹ, chống gù, bảo vệ cột sống hiệu quả với thiết kế nhỏ gọn, hình ảnh đồ họa sinh động, bắt mắt, quai đeo êm ái và đệm lưng thoát nhiệt, thoáng khí sẽ mang đến cảm giác thoải mái, dễ chịu cho bé trong suốt thời gian sử dụng. Balo học sinh tiểu học Sakos Kid Jolly: Siêu nhẹ, chống gù, bảo vệ hiệu quả cột sống của bé Gọn nhẹ – An toàn – Thoải mái chắc chắn là những tiêu chuẩn hàng đầu mà Sakos hướng tới khi cho ra mắt các dòng sản phẩm dành cho trẻ em. Đặc điểm thể chất cùng cấu tạo cơ thể ở độ tuổi này vẫn còn khá non yếu với hệ xương chưa phát triển toàn diện. Chính vì vậy, Sakos luôn đảm bảo những thiết kế dành cho trẻ phải có tính siêu nhẹ, chống gù, bảo vệ hiệu quả cột sống của bé khi phải đeo balo đi học trong thời gian dài. Đặc biệt, khi gặp thời tiết nắng nóng, thiết kế đệm lưng thoát nhiệt, thoáng khí cùng phần quai đeo êm ái sẽ hạn chế gây nóng hầm, khó chịu cũng như trợ lực cho phần vai, lưng để bé đỡ bị mỏi. Ngoài ra, việc sử dụng chất liệu Polyester – loại vải cao cấp sở hữu những phẩm chất tốt như độ bền cao, khả năng chống thấm, hút ẩm và kháng khuẩn hiệu quả, đặc biệt có thể giữ màu sắc lâu phai sẽ giúp Sakos đảm bảo sự an toàn tối ưu cho sức khỏe cùng hệ miễn dịch chưa hoàn thiện của bé. Sakos Kid Jolly: Người bạn đồng hành cùng bé khám phá thế giới tuổi thơ Balo học sinh tiểu học Sakos Kid Jolly sở hữu kiểu dáng độc đáo, giúp bé có thể tháo lắp dễ dàng. Với kích thước nhỏ gọn chỉ 27x15x36 cm cùng các đường may chắc chắn với công nghệ may gấp viền tạo Phom dáng, mang đến sự bền chắc và cứng cáp cho chiếc balo. Đặc biệt, Sakos đã lựa chọn những gam màu nổi bật, rực rỡ như xanh, cam, hồng,… và các họa tiết trang trí với hiệu ứng phản quang sinh động, bắt mắt quen thuộc với thế giới tuổi thơ như nàng tiên cá, mèo con, cún con, khủng long,… Việc tự mình lựa chọn những chiếc balo phù hợp với sở thích của bé sẽ làm tăng niềm yêu thích học tập, cũng như việc đến trường. Xây tính tự lập, dựng thói quen sắp xếp đồ dùng cá nhân theo sở thích của bé Balo học sinh tiểu học Sakos Kid Jolly được phân bổ các ngăn chứa khoa học và tiện lợi. Ngoài không gian chứa đồ bên trong khá rộng rãi, bên trái phần hông của balo còn có túi lưới để ba mẹ có thể để bình nước hoặc hộp sữa cho bé mỗi khi đến lớp. Để tránh tình trạng bị mất hoặc lấy nhầm balo, Sakos bố trí phần nhãn tên để ba mẹ có thể điền thông tin của bé. Ngoài ra, việc trang bị thêm bảng thời khóa biểu sẽ giúp theo dõi lịch học một cách tiện lợi và dễ dàng. Đặc biệt, ba mẹ có thể giúp con yêu xây dựng những thói quen tích cực ngay từ khi còn nhỏ, ví dụ như biết tự sắp xếp đồ dùng cá nhân của mình. Trẻ có thể tự soạn sách vở, hộp viết,… vào balo theo sở thích cá nhân dưới sự quan sát của gia đình, lâu dần sẽ giúp bé hình thành nên tính tự lập và phát triển EQ. Với sự ra đời của balo học sinh tiểu học Sakos Kid Jolly – thành viên mới trong “đại gia đình” balo dành cho trẻ em, Công ty CP Sakos gửi gắm tình yêu thương và hiện thực hóa nó trong từng chi tiết sản phẩm. “Siêu nhẹ – Siêu an toàn – Siêu thoải mái” là những tiêu chí hàng đầu mà Sakos đã và đang theo đuổi trong suốt nhiều năm phục vụ các vị “khách hàng nhí”.', N'https://bizweb.dktcdn.net/100/567/082/products/bia.webp?v=1787734657143', N'images/ADC88225232_01.webp', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 88225232, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/balo-chong-gu-sakos-tieu-hoc-kid-jolly-danh-cho-hoc-sinh-cap-1", "source_collection": "https://adcbook.net.vn/van-phong-pham-dung-cu-hoc-sinh", "scraped_at_utc": "2026-11-03T09:21:28.264557+00:00", "name_vi": "Balo Chống Gù SAKOS Tiểu Học Kid Jolly - Dành Cho Học Sinh Cấp 1", "brand": "Sakos", "vendor": "Sakos", "product_type": "Cặp - Ba Lô Tiểu Học", "category": "do-ban", "color_vi": "Nhiều màu", "color": "multicolor", "material": "Polyester", "dimensions": "27 x 15 x 36 cm", "origin": "Mỹ", "price_vnd": 615000.0, "compare_at_price_vnd": 0, "available": true, "description_vi": "Balo trẻ em Sakos Kid Jolly: Cùng bé đến trường học vui, trải nghiệm tuổi thơ diệu kỳ Ba mẹ luôn dành tặng những điều tuyệt vời và an toàn nhất cho con yêu của mình. Làm thế nào để bé luôn trong trạng thái khỏe mạnh, vui tươi và yêu thích việc học tập mỗi khi đến trường, đây chắc hẳn là mối quan tâm hàng đầu của các bậc phụ huynh. Sakos Kid Jolly là dòng ba lô học sinh tiểu học sở hữu những phẩm chất phù hợp với thể trạng và sức khỏe của các bạn nhỏ: Siêu nhẹ, chống gù, bảo vệ cột sống hiệu quả với thiết kế nhỏ gọn, hình ảnh đồ họa sinh động, bắt mắt, quai đeo êm ái và đệm lưng thoát nhiệt, thoáng khí sẽ mang đến cảm giác thoải mái, dễ chịu cho bé trong suốt thời gian sử dụng. Balo học sinh tiểu học Sakos Kid Jolly: Siêu nhẹ, chống gù, bảo vệ hiệu quả cột sống của bé Gọn nhẹ – An toàn – Thoải mái chắc chắn là những tiêu chuẩn hàng đầu mà Sakos hướng tới khi cho ra mắt các dòng s