tcdn.net/100/567/082/products/balo-hoc-sinh-stargo-wiggy-rainbow-dreams-4-7b24867e-f875-4833-9ab1-90b527e1d68f.jpg?v=1786938753557", "https://bizweb.dktcdn.net/100/567/082/products/balo-hoc-sinh-stargo-wiggy-play-ball-4-e504753d-77b3-4b8c-8ed9-927e4f843798.jpg?v=1786938765487", "https://bizweb.dktcdn.net/100/567/082/products/balo-hoc-sinh-stargo-wiggy-race-road-4-8118ca71-9277-49b3-85e0-08df18924b3f.jpg?v=1786938772883"], "local_images": ["images/ADC88222636_01.png"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T09:21:28.000000', 126), CONVERT(datetime2, N'2026-11-03T09:23:39.000000', 126));
    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (51, N'ADCBook Store', N'88217377', N'https://adcbook.net.vn/balo-chong-gu-sakos-tieu-hoc-stargo-lolly-danh-cho-hoc-sinh-cap-1', N'Balo chống gù SAKOS tiểu học Stargo Lolly - Dành Cho Học Sinh Cấp 1', N'Stargo', N'Cặp - Ba Lô Tiểu Học', N'do-ban', N'multicolor', N'Nhiều màu', 530000.00, 1, N'Balo học sinh Stargo Lolly: Nhẹ vai đến lớp, bền đẹp mỗi ngày Stargo Lolly là mẫu balo học sinh phù hợp cho các bạn nhỏ cần một chiếc cặp vừa nhẹ, vừa tiện lợi để sử dụng hằng ngày. Với kiểu dáng trẻ trung, dễ đeo cùng không gian chứa đồ được bố trí hợp lý, Wiggy giúp bé mang theo sách vở, đồ dùng học tập và vật dụng cá nhân một cách gọn gàng hơn. Sở hữu trọng lượng chỉ 0,5 kg nhưng có khả năng chịu tải lên đến 10 kg, balo vẫn giữ được phom dáng chắc chắn, hạn chế xệ form khi đựng nhiều đồ. Nhẹ nhàng nhưng bền bỉ, Stargo Lolly là người bạn đồng hành đáng tin cậy, giúp bé thêm thoải mái và tự tin trong mỗi ngày đến lớp. Thiết kế tươi sáng, năng động Stargo Lolly gây ấn tượng với kiểu dáng gọn nhẹ, hiện đại cùng bảng màu rực rỡ, phù hợp với sự năng động và đáng yêu của lứa tuổi học sinh. Form balo được thiết kế cân đối với vóc dáng trẻ nhỏ, giúp bé cảm thấy thoải mái khi mang đến lớp, đi chơi hoặc tham gia các hoạt động thường ngày. Bộ sưu tập Stargo Lolly mang đến nhiều họa tiết sinh động như Tweet Mint, Shooting Star, Mermaid Dream, Jungle Dinos, Bunny Cloud, Game Pop, đáp ứng đa dạng sở thích của từng bé. Mỗi thiết kế đều mang màu sắc riêng, tạo cảm giác vui tươi và nổi bật, giúp bé thêm tự tin thể hiện cá tính mỗi ngày. Siêu nhẹ, thoải mái đồng hành mỗi ngày Stargo Lolly nổi bật với thiết kế gọn nhẹ, giúp bé dễ dàng mang balo đến trường mà không gây cảm giác nặng vai hay vướng víu. Nhờ trọng lượng siêu nhẹ, sản phẩm hỗ trợ giảm áp lực lên vai và lưng, phù hợp cho những ngày bé cần mang theo nhiều sách vở, dụng cụ học tập. Balo được làm từ chất liệu polyester bền màu, có khả năng trượt nước, giúp bảo vệ đồ dùng bên trong khi gặp thời tiết ẩm hoặc mưa nhẹ. Bề mặt vải dễ lau sạch, hạn chế bám bẩn, giúp balo luôn giữ được vẻ sạch đẹp trong quá trình sử dụng hằng ngày. Phân ngăn khoa học, sắp xếp gọn gàng Stargo Lolly được thiết kế với hệ thống ngăn chứa hợp lý, giúp bé dễ dàng mang theo sách vở, dụng cụ học tập và các vật dụng cá nhân cần thiết mỗi ngày. Ngăn chính có sức chứa phù hợp cho sách giáo khoa, tập vở, hộp bút, hộp cơm hoặc những món đồ nhỏ bé thường dùng khi đến lớp. Các ngăn phụ được bố trí tiện lợi, hỗ trợ bé sắp xếp bút, thước, sổ tay và vật dụng nhỏ một cách ngăn nắp, dễ lấy khi cần. Bên cạnh đó, balo còn có túi bên hông để đựng bình nước, dù hoặc những món đồ sử dụng thường xuyên, giúp bé chủ động hơn trong suốt ngày dài học tập. Nhờ cách phân chia ngăn khoa học, Stargo Lolly giúp mọi đồ dùng có vị trí riêng, hạn chế lộn xộn và mang lại sự tiện lợi khi bé đến trường, đi chơi hay tham gia các hoạt động hằng ngày. Dây đeo êm ái, đệm lưng thoáng khí Stargo Lolly được thiết kế với dây đeo mềm mại, chắc chắn và có thể điều chỉnh linh hoạt theo vóc dáng của từng bé. Nhờ đó, balo ôm vừa cơ thể hơn, giúp bé cảm thấy thoải mái khi mang theo sách vở, dụng cụ học tập trong suốt ngày dài. Phần lưng balo được trang bị lớp đệm thoáng khí, hỗ trợ thoát nhiệt tốt và tạo cảm giác êm ái khi đeo lâu. Thiết kế này giúp hạn chế cảm giác bí lưng, nặng vai, mang lại sự dễ chịu cho bé khi đến trường, đi chơi hoặc tham gia các hoạt động hằng ngày.', N'https://bizweb.dktcdn.net/100/567/082/products/balo.png?v=1786695656223', N'images/ADC88217377_01.png', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 88217377, "source": "ADCBook Store", 