    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (57, N'ADCBook Store', N'83386271', N'https://adcbook.net.vn/cap-chong-gu-bp-025-hong-t24-tl', N'Cặp Chống Gù BP-025 Hồng/T24 (TL)', N'Thiên Long', N'Cặp - Ba Lô Tiểu Học', N'do-ban', N'pink', N'Hồng', 470000.00, 1, N'Cặp Chống Gù Glubby - Thiên Long BP-025/T24 - Màu Hồng Sản phẩm Cặp Chống Gù cao cấp Thiên Long có hệ thống chống gù toàn diện, thiết kế mặt sau với nhiều cải tiến như: quai đeo trợ lực, đệm mút dày dặn hơn… Kết hợp với chất liệu siêu nhẹ và bền, giúp bé thoải mái và dễ dàng di chuyển. Thiết kế 360 độ tiện lợi khi vệ sinh. Tính Năng Sản Phẩm: - Chống gù toàn diện với đệm mút dày êm giúp chống xô lệch, quai đeo trợ lực, đệm lưng thoát khí, nút điều chỉnh độ dài dây đeo, dây cài ngực. - Có thể điều chỉnh dây đeo phù hợp với từng bé. - Cặp mở được 360 độ vệ sinh dễ dàng. - Chống bụi nấm mốc, chống nước nhẹ và chống thấm. - Thiết kế bắt mắt với nhân vật Akooland độc quyền Thiên Long. - Ngăn chứa rộng rãi giúp giữ thẳng tập sách, có túi phụ co dãn. - Có tính năng phát quang bảo vệ trẻ vào ban đêm. Thông Số Kỹ Thuật - Xuất xứ: Việt Nam. - Kích thước: 37 x 27 x 15 cm (dài x ngang x rộng). - Trọng lượng: 700 gram. - Chất liệu vải: Poly. - Tải trọng: tối đa 8kg.', N'https://bizweb.dktcdn.net/100/567/082/products/1-jfif-a1dd7818-af00-4f24-b189-a301ccea5007.jpg?v=1782274325427', N'images/ADC83386271_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 83386271, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/cap-chong-gu-bp-025-hong-t24-tl", "source_collection": "https://adcbook.net.vn/van-phong-pham-dung-cu-hoc-sinh", "scraped_a