    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (61, N'ADCBook Store', N'83384302', N'https://adcbook.net.vn/balo-lite-bp-038-b-den-tl', N'Balo Lite BP-038/B  Đen (TL)', N'Thiên Long', N'Cặp - Ba Lô - Túi Xách', N'do-ban', N'multicolor', N'Nhiều màu', 290000.00, 1, N'* Thông số kĩ thuật : - Thương hiệu: Thiên Long - Kích thước: 28 x 12 x 38 cm - Trọng lượng: 440 gram - Tải trọng tối đa: 8kg - Chất liệu: Vải polyester phủ PU chống thấm nước, Vải lót 210, Dây kéo Nylon, Nhựa PE, Mousse foam - Tiêu chuẩn: TCCS 033:2010/TL-CHS - Xuất xứ: Việt Nam - Sản xuất: Việt Nam Khuyến cáo: tránh nguồn nhiệt, hóa chất. Không thích hợp cho trẻ dưới 3 tuổi. Balo Lite BP-038 của Thiên Long được thiết kế tối giản nhưng vẫn đảm bảo đầy đủ công năng cho nhu cầu học tập hằng ngày. Với trọng lượng chỉ khoảng 440g, sản phẩm cực kỳ nhẹ, giúp giảm áp lực khi đeo lâu, đặc biệt phù hợp cho học sinh. Chất liệu vải poly cao cấp có khả năng chống thấm nước tốt, giúp bảo vệ sách vở và vật dụng bên trong trong điều kiện thời tiết bất chợt. Thiết kế nhiều ngăn tiện lợi giúp sắp xếp đồ dùng gọn gàng, dễ lấy. Phần lưng balo có rãnh thoát khí kết hợp đệm mút dày, tạo cảm giác êm ái và thông thoáng khi sử dụng. Quai đeo chắc chắn, êm vai, hỗ trợ tốt trong quá trình di chuyển. Sản phẩm có nhiều màu sắc cơ bản như hồng, xanh dương, đen – dễ dàng lựa chọn theo sở thích. Balo được bảo hành chính hãng 12 tháng, đảm bảo chất lượng và độ bền lâu dài.', N'https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-81ztc-mornk8q252ww83-jfif.jpg?v=1782273219513', N'images/ADC83384302_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 83384302,