    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (63, N'ADCBook Store', N'83383294', N'https://adcbook.net.vn/cap-chong-gu-ergo-joy-teddy-bp-037-td-tl', N'Cặp chống gù ERGO JOY - Teddy BP-037/TD (TL)', N'Thiên Long', N'Cặp - Ba Lô Tiểu Học', N'do-ban', N'multicolor', N'Nhiều màu', 470000.00, 1, N'* Thông số kĩ thuật : - Thương hiệu: Thiên Long - Kích thước: 27 x 14 x 37 cm - Trọng lượng: 600 gram - Tải trọng tối đa: 10 kg - Chất liệu: Vải polyester phủ PVC chống thấm nước, vải lót 210, Simili PVC, dây kéo nylon, Mousse PE. - Tiêu chuẩn: TCCS 033:2010/TL-CHS - Xuất xứ: Việt Nam - Sản xuất: Việt Nam Khuyến cáo: tránh nguồn nhiệt, hóa chất. Không thích hợp cho trẻ dưới 3 tuổi. Cặp chống gù ERGO JOY - Teddy BP-037 là dòng balo học sinh thiết kế công thái học, giúp giảm áp lực lên vai và lưng, hỗ trợ bé giữ dáng chuẩn trong suốt quá trình học tập. Sản phẩm kết hợp nhiều họa tiết sinh động, phù hợp cả bé trai và bé gái. Thiết kế chống gù chuẩn công thái học, phân bổ lực đều hai vai Quai đeo chữ S ôm sát, đệm mút dày êm, rãnh thoáng khí giúp đeo lâu không nóng Chất liệu vải Poly siêu nhẹ, chống thấm nước, hạn chế bám bẩn và nấm mốc Mở balo 360° tiện lợi, dễ dàng sắp xếp và vệ sinh Dây khóa kéo êm, trơn mượt, bền bỉ khi sử dụng lâu dài Ngăn chứa rộng rãi, phù hợp sách vở và dụng cụ học tập Tải trọng tối đa lên đến 10kg, đáp ứng nhu cầu học sinh tiểu học Đa dạng mẫu mã: dễ thương, năng động, cá tính. Sản phẩm phù hợp cho học sinh tiểu học, giúp bé đi học nhẹ nhàng hơn mỗi ngày, đồng thời bảo vệ cột sống ngay từ sớm.', N'https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-81ztc-mpbpneiqg55a70-jfif.jpg?v=1782271993387', N'images/ADC83383294_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 83383294, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/cap-chong-gu-ergo-joy-teddy-bp-037-td-tl", "source_collection": "https://adcbook.net.vn/van-phong-pham-dung-cu-hoc-sinh", "scraped_at_utc": "2026-11-03T09:21:28.264557+00:00", "name_vi": "Cặp chống gù ERGO JOY - Teddy BP-037/TD (TL)", "brand": "Thiên Long", "vendor": "Thiên Long", "product_type": "Cặp - Ba Lô Tiểu Học", "category": "do-ban", "color_vi": "Nhiều màu", "color": "multicolor", "material": "Vải Poli", "dimensions": "27 x 14 x 37 cm", "origin": "Việt Nam", "price_vnd": 470000.0, "compare_at_price_vnd": 0, "available": true, "description_vi": "* Thông số kĩ thuật : - Thương hiệu: Thiên Long - Kích thước: 27 x 14 x 37 cm - Trọng lượng: 600 gram - Tải trọng tối đa: 10 kg - Chất liệu: Vải polyester phủ PVC chống thấm nước, vải lót 210, Simili PVC, dây kéo nylon, Mousse PE. - Tiêu chuẩn: TCCS 033:2010/TL-CHS - Xuất xứ: Việt Nam - Sản xuất: Việt Nam Khuyến cáo: tránh nguồn nhiệt, hóa chất. Không thích hợp cho trẻ dưới 3 tuổi. Cặp chống gù ERGO JOY - Teddy BP-037 là dòng balo học sinh thiết kế công thái học, giúp giảm áp lực lên vai và lưng, hỗ trợ bé giữ dáng chuẩn trong suốt quá trình học tập. Sản phẩm kết hợp nhiều họa tiết sinh động, phù hợp cả bé trai và bé gái. Thiết kế chống gù chuẩn công thái học, phân bổ lực đều hai vai Quai đeo chữ S ôm sát, đệm mút dày êm, rãnh thoáng khí giúp đeo lâu không nóng Chất liệu vải Poly siêu nhẹ, chống thấm nước, hạn chế bám bẩn và nấm mốc Mở balo 360° tiện lợi, dễ dàng sắp xếp và vệ sinh Dây khóa kéo êm, trơn mượt, bền bỉ khi sử dụng lâu dài Ngăn chứa rộng rãi, phù hợp sách vở và dụng cụ học tập Tải trọng tối đa lên đến 10kg, đáp ứng nhu cầu học sinh tiểu học Đa dạng mẫu mã: dễ thương, năng động, cá tính. Sản phẩm phù hợp cho học sinh tiểu học, giúp bé đi học nhẹ nhàng hơn mỗi ngày, đồng thời bảo vệ cột sống ngay từ sớm.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-81ztc-mpbpneiqg55a70-jfif.jpg?v=1782271993387", "https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-81ztc-mpbplzjej4lc6d-jfif.jpg?v=1782272007563"], "local_images": ["images/ADC83383294_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T09:21:28.000000', 126), CONVERT(datetime2, N'2026-11-03T09:23:39.000000', 126));
    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (64, N'ADCBook Store', N'83383292', N'https://adcbook.net.vn/balo-lite-bp-038-p-hong-tl', N'Balo Lite BP-038/P Hồng (TL)', N'Thiên Long', N'Cặp - Ba Lô - Túi Xách', N'do-ban', N'multicolor', N'Nhiều màu', 290000.00, 1, N'* Thông số kĩ thuật : - Thương hiệu: Thiên Long - Kích thước: 28 x 12 x 38 cm - Trọng lượng: 440 gram - Tải trọng tối đa: 8 kg - Chất liệu: Vải polyester phủ PU chống thấm nước, Vải lót 210, Dây kéo Nylon, Nhựa PE, Mousse foam - Tiêu chuẩn: TCCS 033:2010/TL-CHS - Xuất xứ: Việt Nam - Sản xuất: Việt Nam Khuyến cáo: tránh nguồn nhiệt, hóa chất. Không thích hợp cho trẻ dưới 3 tuổi. Balo Lite BP-038 của Thiên Long được thiết kế tối giản nhưng vẫn đảm bảo đầy đủ công năng cho nhu cầu học tập hằng ngày. Với trọng lượng chỉ khoảng 440g, sản phẩm cực kỳ nhẹ, giúp giảm áp lực khi đeo lâu, đặc biệt phù hợp cho học sinh. Chất liệu vải poly cao cấp có khả năng chống thấm nước tốt, giúp bảo vệ sách vở và vật dụng bên trong trong điều kiện thời tiết bất chợt. Thiết kế nhiều ngăn tiện lợi giúp sắp xếp đồ dùng gọn gàng, dễ lấy. Phần lưng balo có rãnh thoát khí kết hợp đệm mút dày, tạo cảm giác êm ái và thông thoáng khi sử dụng. Quai đeo chắc chắn, êm vai, hỗ trợ tốt trong quá trình di chuyển. Sản phẩm có nhiều màu sắc cơ bản như hồng, xanh dương, đen – dễ dàng lựa chọn theo sở thích. Balo được bảo hành chính hãng 12 tháng, đảm bảo chất lượng và độ bền lâu dài.', N'https://bizweb.dktcdn.net/100/567/082/products/vn-11134207-81ztc-mornkbv4nu32ef-jfif.jpg?v=1782272670400', N'images/ADC83383292_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 8338329