    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (70, N'ADCBook Store', N'76899009', N'https://adcbook.net.vn/sun-eight-22222-balo-hoc-sinh-cap-1-sieu-nhe-chong-gu-chong-tham-nuoc-tui-tho-hong-pink-kt-42x29-5x14-5cm-1', N'Balo Chống Gù Học Sinh Cấp 1 - Gấu Xanh, Cam SUN EIGHT - 22222', N'Sun Eight', N'Cặp - Ba Lô Tiểu Học', N'do-ban', N'multicolor', N'Nhiều màu', 635000.00, 1, N'Balo Tiểu Học SUN EIGHT 22222 – Cặp Chống Gù, Nhẹ Vai, Chống Nước Cho Bé Cấp 1 - Chất liệu: Vải polyester chống co giãn, chống nhăn tốt - Sản phẩm của SUN EIGHT - Kích thước: 42x29.5x14.5cm Balo học sinh SUN EIGHT 22222 mang đến sự thoải mái và tiện lợi cho bé trong suốt năm học. Với trọng lượng siêu nhẹ, thiết kế lưng đệm chống cong vẹo và chất liệu kháng nước, sản phẩm giúp bé yên tâm đến trường mỗi ngày. Ngăn chứa rộng, chia ngăn hợp lý giúp sắp xếp sách vở và đồ dùng học tập dễ dàng. Quai đeo có đệm mềm, điều chỉnh linh hoạt theo chiều cao của bé. Kiểu dáng năng động, phù hợp với học sinh tiểu học từ lớp 1 đến lớp 5. Là lựa chọn lý tưởng để đồng hành cùng bé trong môi trường học đường năng động và hiện đại.', N'https://bizweb.dktcdn.net/100/567/082/products/sg-11134201-821fz-mgytjrtjz5zffb-jfif.jpg?v=1783582193707', N'images/ADC76899009_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 76899009, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/sun-eight-22222-balo-hoc-sinh-cap-1-sieu-nhe-chong-gu-chong-tham-nuoc-tui-tho-hong-pink-kt-42x29-5x14-5cm-1", "source_collection": "https://adcbook.net.vn/van-phong-pham-dung-cu-hoc-sinh", "scraped_at_utc": "2026-11-03T09:21:28.264557+00:00", "name_vi": "Balo C