    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (73, N'ADCBook Store', N'46337710', N'https://adcbook.net.vn/but-sap-dau-12-mau-chuot-faber-castell-120063on-12-mau-hop', N'Bút Sáp Dầu 12 Màu + Chuốt Faber-Castell 120063ON (12 Màu/hộp)', N'Faber-Castell', N'Bút Vẽ', N'but-viet', N'multicolor', N'Nhiều màu', 81000.00, 1, N'Sáp màu dầu *Không độc hại-sử dụng màu thực phẩm-an toàn cho người dùng. *Thân bút bọc bằng giấy giúp tay cầm bút không dính bẩn và giữ bút khó bị gãy. *Đường kính 11mm giúp dễ nắm; Lý tưởng cho trẻ em. *Màu sắc sống động, tươi sáng, dễ phối màu. *Kèm sách hướng dẫn mô tả, hướng dẫn về màu sắc. *Dễ dàng giặt sạch vết mực bẩn trên quần áo. *Kèm dụng cụ chuốt và nối dài bút. *An toàn cho trẻ em.', N'https://bizweb.dktcdn.net/100/567/082/products/image1920-a7c8c353-30bb-4e31-bcda-046f481db9a5.jpg?v=1747061995193', N'images/ADC46337710_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 46337710, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/but-sap-dau-12-mau-chuot-faber-castell-120063on-12-mau-hop", "source_collection": "https://adcbook.net.vn/dung-cu-ve", "scraped_at_utc": "2026-11-03T09:21:28.264557+00:00", "name_vi": "Bút Sáp Dầu 12 Màu + Chuốt Faber-Castell 120063ON (12 Màu/hộp)", "brand": "Faber-Castell", "vendor": "CÔNG TY TNHH ĐẦU TƯ THƯƠNG MẠI CON ONG XANH (Ký gửi)", "product_type": "Bút Vẽ", "category": "but-viet", "color_vi": "Nhiều màu", "color": "multicolor", "material": "Nhựa", "dimensions": "17 x 8.5 x 2 cm", "origin": "Đức", "price_vnd": 81000.0, "compare_at_price_vnd": 0, "available": true, "description_vi": "Sáp màu dầu *Không độc hại-sử dụng màu thực phẩm-an toàn cho người dùng. *Thân bút bọc bằng giấy giúp tay cầm bút không dính bẩn và giữ bút khó bị gãy. *Đường kính 11mm giúp dễ nắm; Lý tưởng cho trẻ em. *Màu sắc sống động, tươi sáng, dễ phối màu. *Kèm sách hướng dẫn mô tả, hướng dẫn về màu sắc. *Dễ dàng giặt sạch vết mực bẩn trên quần áo. *Kèm dụng cụ chuốt và nối dài bút. *An toàn cho trẻ em.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/image1920-a7c8c353-30bb-4e31-bcda-046f481db9a5.jpg?v=1747061995193", "https://bizweb.dktcdn.net/100/567/082/products/image1920-d9d3e31d-9ab9-4dc2-b6ad-538d909117a0.jpg?v=1747061995193", "https://bizweb.dktcdn.net/100/567/082/products/image1920-6c148156-fc2b-496d-9e4e-2f6577f8de69.jpg?v=1747061995193", "https://bizweb.dktcdn.net/100/567/082/products/image1920-9f1cc3bf-fc49-49f7-8f6b-d3f3cbdac6d2.jpg?v=1747061995193", "https://bizweb.dktcdn.net/100/567/082/products/image1920-5591efdc-765b-40ef-89e8-8cfa868b43f3.jpg?v=1747061995193", "https://bizweb.dktcdn.net/100/567/082/products/image1920-00fce8de-ab68-49ea-a38c-518fa1549bab.jpg?v=1747061995193"], "local_images": ["images/ADC46337710_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T09:21:28.000000', 126), CONVERT(datetime2, N'2026-11-03T09:23:39.000000', 126));
