rip và chuốt. *An toàn cho trẻ em.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/image1920-4c4c694b-7285-4258-a339-a038b98012da.jpg?v=1747061972343", "https://bizweb.dktcdn.net/100/567/082/products/image1920-4e8e637b-1eef-487c-b268-60eeaeb845dc.jpg?v=1747061972343", "https://bizweb.dktcdn.net/100/567/082/products/image1920-31e90276-b69e-4817-bc5d-bb1b8eaaf0d4.jpg?v=1747061972343", "https://bizweb.dktcdn.net/100/567/082/products/image1920-03bd7e86-dfb5-4c0a-8758-b8c1786f3cac.jpg?v=1747061972343"], "local_images": ["images/ADC46337681_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T09:21:28.000000', 126), CONVERT(datetime2, N'2026-11-03T09:23:39.000000', 126));
    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (75, N'ADCBook Store', N'46337580', N'https://adcbook.net.vn/but-chi-staedtler-48-mau-136c48', N'Bút Chì Staedtler 48 Màu 136C48', N'Staedtler', N'Bút Vẽ', N'but-viet', N'multicolor', N'Nhiều màu', 199000.00, 1, N'Bút chì màu Steadtler Luna 136 C48 được sản xuất từ các nguyên liệu chất lượng đảm bảo an toàn khi sử dụng. Ngòi bút rất mềm mại, dễ tô màu trên các chất liệu và lâu mòn, giúp tiết kiệm chi phí khi sử dụng. Hộp sản phẩm gồm 48 chiếc bút với 48 màu khác nhau, đáp ứng được nhu cầu tô màu của bạn. Các màu sắc mịn màng, gần giống với màu thực tế, đem đến vẻ đẹp và sự sinh động cho các bức tranh. Bút chì rất dễ gọt, có độ bền cao, khó bị gãy khi tô màu hoặc khi bị rơi. Đặc biệt, các nét chì rất sắc nét, không bị lem màu vào tay trong quá trình sử dụng. Hộp sản phẩm có hình vẽ rất dễ thương, thích hợp để dành tặng cho các bé.', N'https://bizweb.dktcdn.net/100/567/082/products/image1920-5529a66b-f251-4338-b710-7142f9d395af-9f9d5484-0c30-447c-99bc-3d8f1475bf67.jpg?v=1747327816690', N'images/ADC46337580_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 46337580, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/but-chi-staedtler-48-mau-136c48", "source_collection": "https://adcbook.net.vn/dung-cu-ve", "scraped_at_utc": "2026-11-03T09:21:28.264557+00:00", "name_vi": "Bút Chì Staedtler 48 Màu 136C48", "brand": "Staedtler", "vendor": "Staedtler", "product_type": "Bút Vẽ", "category": "but-viet", "color_vi": "Nhiều màu", "color": "multicolor", "material": "Gỗ", "dimensions": "", "origin": "Đức", "price_vnd": 199000.0, "compare_at_price_vnd": 0, "available": true, "description_vi": "Bút chì màu Steadtler Luna 136 C48 được sản xuất từ các nguyên liệu chất lượng đảm bảo an toàn khi sử dụng. Ngòi bút rất mềm mại, dễ tô màu trên các chất liệu và lâu mòn, giúp tiết kiệm chi phí khi sử dụng. Hộp sản phẩm gồm 48 chiếc bút với 48 màu khác nhau, đáp ứng được nhu cầu tô màu của bạn. Các màu sắc mịn màng, gần giống với màu thực tế, đem đến vẻ đẹp và sự sinh động cho các bức tranh. Bút chì rất dễ gọt, có độ bền cao, khó bị gãy khi tô màu hoặc khi bị rơi. Đặc biệt, các nét chì rất sắc nét, không bị lem màu vào tay trong quá trình sử dụng. Hộp sản phẩm có hình vẽ rất dễ thương, thích hợp để dành tặng cho các bé.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/image1920-5529a66b-f251-4338-b710-7142f9d395af-9f9d5484-0c30-447c-99bc-3d8f1475bf67.jpg?v=1747327816690"], "local_images": ["images/ADC46337580_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T09:21:28.000000', 126), CONVERT(datetime2, N'2026-11-03T09:23:39.000000', 126));
