    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (80, N'ADCBook Store', N'46333824', N'https://adcbook.net.vn/vi-dung-tien-xu-tien-le-airpod-hoat-hinh-de-thuong', N'Ví Đựng Tiền Xu - Tiền Lẻ - Airpod Hoạt Hình Dễ Thương', N'CÔNG TY CỔ PHẦN GIÁO DỤC BILI VIỆT NAM', N'Dụng Cụ Học Sinh Khác', N'do-ban', N'multicolor', N'Nhiều màu', 18000.00, 1, N'Ví Đựng Tiền Xu - Tiền Lẻ - Airpod Hoạt Hình Dễ Thương Phân loại: Văn phòng phẩm - Dụng cụ học sinh, phụ kiện học đường Chất liệu: Vải mềm, bền đẹp, thân thiện với người dùng Màu sắc: Nhiều màu sắc tươi sáng, dễ phối với các vật dụng khác Kích thước: 14 x 11 x 1 cm - nhỏ gọn, tiện lợi mang theo Trọng lượng: Chỉ 50g - nhẹ nhàng, dễ cầm nắm Độ tuổi khuyến nghị: Phù hợp cho trẻ em từ 3 tuổi trở lên Đặc điểm nổi bật: Thiết kế hoạt hình dễ thương: Kiểu dáng ngộ nghĩnh, đáng yêu, tạo điểm nhấn cá nhân Công năng đa dụng: Phù hợp để đựng tiền xu, tiền lẻ hoặc tai nghe AirPods Quà tặng ý nghĩa: Lựa chọn lý tưởng làm quà tặng cho bé yêu hoặc bạn bè Sản phẩm chính hãng: Nhập khẩu và phân phối bởi Công ty CP Giáo dục Bili Việt Nam Xuất xứ: Sản xuất tại Trung Quốc Hướng dẫn và lưu ý sử dụng: Sử dụng cho mục đích cá nhân hoặc làm quà tặng Bảo quản nơi khô ráo, tránh nhiệt độ cao và lửa Ví Đựng Tiền Xu - Tiền Lẻ - Airpod Hoạt Hình Dễ Thương là món phụ kiện nhỏ xinh, vừa giúp bảo quản đồ dùng ngăn nắp, vừa thể hiện phong cách đáng yêu, năng động.', N'https://bizweb.dktcdn.net/100/567/082/products/3023.jpg?v=1747059875230', N'images/ADC46333824_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 46333824, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/vi-d