    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (83, N'ADCBook Store', N'46332405', N'https://adcbook.net.vn/vi-3-but-da-kim-fl04-do-mau-tim', N'Vỉ 3 Bút Dạ Kim FL04/DO - Màu Tím', N'Thiên Long', N'Bút Lông', N'but-viet', N'purple', N'Tím', 26000.00, 1, N'Vỉ 3 Bút Lông Kim FL-04/DO - Mực Tím Thông số kĩ thuật : Thương hiệu Thiên Long Đường kính viên bi 0.5mm Tính năng nổi bật: Bút có thiết kế đơn giản và hiện đại. Thân và nắp bút bằng nhựa trắng đục, tảm nhựa pha màu theo màu mực của ruột. Thân bút tròn và nhỏ rất phù hợp với tay cầm của HS. Mực cho màu đậm và tươi sáng, viết rất nhẹ và êm trơn. Đặc điểm bút : Đầu bi: 0.5mm,, sản suất tại Thụy Sĩ. Độ dài viết được: 500-1000m. Mực đạt chuẩn: ASTM D-4236, EN71/3. Lợi ích: Thiết kế bút hiện đại, được in bằng kỹ thuật cao cấp làm tăng thêm tính sang trọng cho sản phẩm Bảo quản: Tránh va chạm vào các vật cứng quá mạnh. Tránh để sản phẩm ở gần nhiệt độ quá cao. Đặc điểm nổi bật: Bút Gel là nhãn hàng Bút viết ra đời nhằm mang đến sự tiện lợi, thoải mái cho người sử dụng. Thiết kế bút phù hợp với người Việt, tạo cho người viết không bị mỏi tay. Đầu bi cao cấp giúp mực trợn mượt, phù hợp cho người viết nhiều, tốc ký như học sinh phổ thông, sinh viên. Vỏ bút làm bằng nhựa trong giúp người viết dễ dàng kiểm tra lượng mực của bút, viết được đến khi hết mực mà không lo tắc hay lắng cặn. Với thiết kế trang nhã, màu sắc tươi sáng phù hợp với nhu cầu sử dụng của nhiều người, Bút Gel đã trở thành người bạn đồng hành của nhiều học sinh.', N'https://bizweb.dktcdn.net/100/567/082/products/image1920-40112ec6-6f9e-4082-855a-d7adaa40a437.jpg?v=1747059463493', N'images/ADC46332405_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 46332405, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/vi-3-but-da-kim-fl04-do-mau-tim", "source_collection": "https://adcbook.net.vn/but-long", "scraped_at_utc": "2026-11-03T09:21:28.264557+00:00", "name_vi": "Vỉ 3 Bút Dạ Kim FL04/DO - Màu Tím", "brand": "Thiên Long", "vendor": "Thiên Long", "product_type": "Bút Lông", "category": "but-viet", "color_vi": "Tím", "color": "purple", "material": "", "dimensions": "", "origin": "Việt Nam", "price_vnd": 26000.0, "compare_at_price_vnd": 0, "available": true, "description_vi": "Vỉ 3 Bút Lông Kim FL-04/DO - Mực Tím Thông số kĩ thuật : Thương hiệu Thiên Long Đường kính viên bi 0.5mm Tính năng nổi bật: Bút có thiết kế đơn giản và hiện đại. Thân và nắp bút bằng nhựa trắng đục, tảm nhựa pha màu theo màu mực của ruột. Thân bút tròn và nhỏ rất phù hợp với tay cầm của HS. Mực cho màu đậm và tươi sáng, viết rất nhẹ và êm trơn. Đặc điểm bút : Đầu bi: 0.5mm,, sản suất tại Thụy Sĩ. Độ dài viết được: 500-1000m. Mực đạt chuẩn: ASTM D-4236, EN71/3. Lợi ích: Thiết kế bút hiện đại, được in bằng kỹ thuật cao cấp làm tăng thêm tính sang trọng cho sản phẩm Bảo quản: Tránh va chạm vào các vật cứng quá mạnh. Tránh để sản phẩm ở gần nhiệt độ quá cao. Đặc điểm nổi bật: Bút Gel là nhãn hàng Bút viết ra đời nhằm mang đến sự tiện lợi, thoải mái cho người sử dụng. Thiết kế bút phù hợp với người Việt, tạo cho người viết không bị mỏi tay. Đầu bi cao cấp giúp mực trợn mượt, phù hợp cho người viết nhiều, tốc ký như học sinh phổ thông, sinh viên. Vỏ bút làm bằng nhựa trong giúp người viết dễ dàng kiểm tra lượng mực của bút, viết được đến khi hết mực mà không lo tắc hay lắng cặn. Với thiết kế trang nhã, màu sắc tươi sáng phù hợp với nhu cầu sử dụng của nhiều người, Bút Gel đã trở thành người bạn đồng hành của nhiều học sinh.", "image_urls": ["https://bizweb.dktcdn.net/100/567/082/products/image1920-40112ec6-6f9e-4082-855a-d7adaa40a437.jpg?v=1747059463493", "https://bizweb.dktcdn.net/100/567/082/products/image1920-bca928ee-e7e7-4fca-9a6d-a8d303de3784.jpg?v=1747059463493", "https://bizweb.dktcdn.net/100/567/082/products/image1920-da33a07f-f277-4efe-a35e-2fe76527871d.jpg?v=1747059463493", "https://bizweb.dktcdn.net/100/567/082/products/image1920-7fe4d5f8-efea-4dee-a76f-8dc850a3ce54.jpg?v=1747059463493"], "local_images": ["images/ADC46332405_01.jpg"], "image_rights_note": "Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại."}', CONVERT(datetime2, N'2026-11-03T09:21:28.000000', 126), CONVERT(datetime2, N'2026-11-03T09:23:39.000000', 126));
    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (84, N'ADCBook Store', N'46341102', N'https://adcbook.net.vn/may-tinh-van-phong-canonas-120-ii', N'Máy Tính Văn Phòng Canon AS-120 II', N'Canon', N'Máy Tính Văn Phòng', N'do-ban', N'black', N'Màu Đen', 190000.00, 1, N'Máy Tính Văn Phòng Canon AS-120 II 1. MÔ TẢ SẢN PHẨM Máy Tính Để Bàn Canon AS-120 II ASA HB, với thiết kế đế cong cùng màn hình LCD có độ phân giải cao giúp người dùng dễ dàng quan sát màn hình và sử dụng. Chất liệu kháng vân tay và mồ hôi cao cấp, các chức năng phù hợp sử dụng tính toán cho khối kinh doanh và khối văn phòng. Máy Tính Cầm Tay Canon AS-120 II ASA HB là công cụ tính toán hoàn hảo cho dân văn phòng và chủ cửa hàng. 2. THÔNG SỐ KỸ THUẬT Mã hàng: AS-120 II ASA HB Hiển thị: 12 số Màu sắc: Đen. Kích thước:144 x 100 x 29.3mm Trọng lượng: 104g Xuất xứ thương hiệu: Nhật Bản 3. ĐẶC ĐIỂM SẢN PHẨM Sản phẩm thuộc dòng AS Series - cải tiến phần đế cong giúp dễ dàng quan sát màn hình. Màn hình LCD lớn, có độ phân giải cao. Sử dụng chất liệu kháng vân tay. Sử dụng 2 nguồn điện: năng lượng ánh sáng và pin. Có chức năng ghi nhớ các giá trị để tính tổng. 4. ĐỐI TƯỢNG SỬ DỤNG Phù hợp với cho dân văn phòng, kế toán, nhân viên kinh doanh và chủ cửa hàng. 5. CẢNH BÁO Tránh xa tầm tay trẻ em Tránh xa nguồn nhiệt và nơi có độ ẩm cao.', N'https://bizweb.dktcdn.net/100/567/082/products/canon-calculator-as-120-ii-asa-hb-1.jpg?v=1747065322367', N'images/ADC46341102_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 46341102, "source": "ADCBook Store", "source_url": "https://adcbook.net.vn/may-tinh-van-phong-canonas-120-ii", "source_collection": "