    INSERT INTO dbo.[ExternalProductStaging] ([ExternalProductId], [SourceName], [SourceProductId], [SourceUrl], [NameVi], [Brand], [ProductType], [Category], [Color], [ColorVi], [Price], [IsAvailable], [DescriptionVi], [ImageUrl], [LocalImagePath], [ImageRightsNote], [SourceJson], [ScrapedAt], [ImportedAt]) VALUES (87, N'ADCBook Store', N'53805454', N'https://adcbook.net.vn/hky-tt02-tui-vai-nhan-vat-haikyu-5-nhan-vat-showa', N'Túi Vải Nhân Vật Haikyu - 5 Nhân Vật [Hky-Tt02]', N'CÔNG TY TNHH SHOWA BRAIN NAVI VIỆT NAM  (KÝ GỬI)', N'Ba lô, căp, túi (Phương NTT)', N'do-ban', N'multicolor', N'Nhiều màu', 190000.00, 1, N'Túi Vải Tote Nhân Vật Haikyu - Wedge Holdings HKY-TT02 - Hình 5 Nhân Vật Sản phẩm Túi tote Nhân vật Dragon on Hat là sản phẩm mới nhất trong chuỗi các sản phẩm độc quyền phát hành tại thị trường Việt Nâm từ Tác giả, Họa sĩ nổi tiếng Nhật Ban - Akira Ito. Họa sĩ Nhật Bản - Akira Ito là tác giả của bộ ngoại truyện Yu-Gi-Oh R nổi tiếng trên thế giới, đồng thời Họa sĩ Akira Ito còn là tác giả của series Cardfight Vanguard, một series bao gồm các ấn phẩm Anime, Manga, và Trading Card Game. Với dự án mới nhất Dragon on Hat, tác giả trình làng các sản phẩm mới mang thương hiệu độc quyền phân phối tại Việt Nam, bìa hồ sơ nhân vật Dragon on Hat là một trong số các sản phẩm đặc biệt lần này. Với hình ảnh được in ấn rõ nét, đạt chất lượng gần như hoàn hảo, hình ảnh Công chúa Hoa và chú rồng trắng Yapan được tái hiện sinh động đầy màu sắc, bên cạnh đó còn được nhập khẩu trực tiếp từ Nhà sản xuất Wedge Holdings Nhật Bản. Sản phẩm không chỉ là vật dụng hữu ích hàng ngày giúp các bạn mang theo bên mình tiện dụng khắp mọi nơi, mà còn là sản phẩm sưu tập cực kỳ đẹp và thú vị.', N'https://bizweb.dktcdn.net/100/567/082/products/4573471739800.jpg?v=1753523320630', N'images/ADC53805454_01.jpg', N'Ảnh sản phẩm từ ADCBook/Bizweb; chỉ dùng cho prototype nội bộ. Cần xin phép chủ sở hữu trước khi phân phối hoặc sử dụng thương mại.', N'{"source_id": 53805454, "source": "ADCBook St